var tipuesearch = {"pages":[{"title":" SPECTRUM ","text":"SPECTRUM Developer Info Jason Christopherson","tags":"home","loc":"index.html"},{"title":"stft_result – SPECTRUM ","text":"type, public :: stft_result A container for STFT output. Components Type Visibility Attributes Name Initial integer(kind=int32), public, allocatable, dimension(:) :: offsets The starting indices of each window segment. complex(kind=real64), public, allocatable, dimension(:,:) :: stft An M-by-N matrix containing the M-element complex-valued \ntransforms for each of the N time points studied.  M is the \nsize of the positive half of the transform, and N is the total \nnumber of transformed segments.","tags":"","loc":"type\\stft_result.html"},{"title":"blackman_harris_window – SPECTRUM ","text":"type, public, extends( window ) :: blackman_harris_window Defines a Blackman-Harris window. See Also Wikipedia Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure, public :: evaluate => bhw_eval private pure function bhw_eval(this, bin) result(rst) Evaluates the window function. Arguments Type Intent Optional Attributes Name class( blackman_harris_window ), intent(in) :: this The blackman_harris_window object. integer(kind=int32), intent(in) :: bin The index or bin number [0, n], where n is the window size. Return Value real(kind=real64) The function value.","tags":"","loc":"type\\blackman_harris_window.html"},{"title":"flat_top_window – SPECTRUM ","text":"type, public, extends( window ) :: flat_top_window Defines a flat-top window. See Also Wikipedia Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure, public :: evaluate => ftw_eval private pure function ftw_eval(this, bin) result(rst) Evaluates the window function. Arguments Type Intent Optional Attributes Name class( flat_top_window ), intent(in) :: this The flat_top_window object. integer(kind=int32), intent(in) :: bin The index or bin number [0, n], where n is the window size. Return Value real(kind=real64) The function value.","tags":"","loc":"type\\flat_top_window.html"},{"title":"hamming_window – SPECTRUM ","text":"type, public, extends( window ) :: hamming_window Defines a Hamming window. See Also Wikipedia Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure, public :: evaluate => hamming_eval private pure function hamming_eval(this, bin) result(rst) Evaluates the window function. Arguments Type Intent Optional Attributes Name class( hamming_window ), intent(in) :: this The hamming_window object. integer(kind=int32), intent(in) :: bin The index or bin number [0, n], where n is the window size. Return Value real(kind=real64) The function value.","tags":"","loc":"type\\hamming_window.html"},{"title":"hann_window – SPECTRUM ","text":"type, public, extends( window ) :: hann_window Defines a Hann window. . See Also Wikipedia Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure, public :: evaluate => hann_eval private pure function hann_eval(this, bin) result(rst) Evaluates the window function. Arguments Type Intent Optional Attributes Name class( hann_window ), intent(in) :: this The hann_window object. integer(kind=int32), intent(in) :: bin The index or bin number [0, n], where n is the window size. Return Value real(kind=real64) The function value.","tags":"","loc":"type\\hann_window.html"},{"title":"rectangular_window – SPECTRUM ","text":"type, public, extends( window ) :: rectangular_window @brief Defines a rectangular window.\nDefines a rectangular window. Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure, public :: evaluate => rw_eval private pure function rw_eval(this, bin) result(rst) Evaluates the window function. Arguments Type Intent Optional Attributes Name class( rectangular_window ), intent(in) :: this The rectangular_window object. integer(kind=int32), intent(in) :: bin The index or bin number [0, n], where n is the window size. Return Value real(kind=real64) The function value.","tags":"","loc":"type\\rectangular_window.html"},{"title":"welch_window – SPECTRUM ","text":"type, public, extends( window ) :: welch_window Defines a Welch window. See Also Wikipedia Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure, public :: evaluate => welch_eval private pure function welch_eval(this, bin) result(rst) Evaluates the window function. Arguments Type Intent Optional Attributes Name class( welch_window ), intent(in) :: this The welch_window object. integer(kind=int32), intent(in) :: bin The index or bin number [0, n], where n is the window size. Return Value real(kind=real64) The function value.","tags":"","loc":"type\\welch_window.html"},{"title":"window – SPECTRUM ","text":"type, public :: window Defines the structure of a window. Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure( window_function ), public, deferred, pass :: evaluate pure function window_function(this, bin) result(rst) Prototype Evaluates the window function. Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: this The window object. integer(kind=int32), intent(in) :: bin The index or bin number [0, n], where n is the window size. Return Value real(kind=real64) The function value.","tags":"","loc":"type\\window.html"},{"title":"integrate – SPECTRUM","text":"public pure function integrate(dt, x, iv) result(rst) Integrates a data set. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: dt The sample interval. real(kind=real64), intent(in), dimension(:) :: x The data set to integrate. real(kind=real64), intent(in), optional :: iv The initial value.  The default value is zero. Return Value real(kind=real64), allocatable, dimension(:) The integrated data set.","tags":"","loc":"proc\\integrate.html"},{"title":"irfft – SPECTRUM","text":"public pure function irfft(x, n) result(rst) Computes the inverse Fourier transform for a real-valued data set. Arguments Type Intent Optional Attributes Name complex(kind=real64), intent(in), dimension(:) :: x The positive half of the transform. integer(kind=int32), intent(in), optional :: n An optional input that can be used to specify the length of the \ntransform.  If less than the length of x, x is truncated; however, \nif greater than the length of x, x is padded with zeros. Return Value real(kind=real64), allocatable, dimension(:) The real-valued result of the inverse transform.","tags":"","loc":"proc\\irfft.html"},{"title":"rfft – SPECTRUM","text":"public pure function rfft(x, n) result(rst) Computes the Fourier transform of a real-valued data set.  Only the \npositive half of the transform is returned. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in), dimension(:) :: x The real-valued array to transform. integer(kind=int32), intent(in), optional :: n An optional input that can be used to specify the length of the \ntransform.  If less than the length of x, x is truncated; however, \nif greater than the length of x, x is padded with zeros. Return Value complex(kind=real64), allocatable, dimension(:) The complex-valued result of the transform.","tags":"","loc":"proc\\rfft.html"},{"title":"stft – SPECTRUM","text":"public pure function stft(win, x) result(rst) Computes the short time Fourier transform of a signal. See Also Wikipedia - Short Time Fourier Transform Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window to apply. real(kind=real64), intent(in) :: x (:) The signal to analyze.  The signal must be longer than the size of \nthe window. Return Value type( stft_result ) A container filled with the transform results.","tags":"","loc":"proc\\stft.html"},{"title":"filter – SPECTRUM","text":"public pure function filter(b, a, x, delays) result(rst) Applies the specified filter to a signal. The description of the filter in the Z-transform domain is a rational\ntransfer function of the form: ,\nwhich handles both IIR and FIR filters. The above form assumes a\nnormalization of a(1) = 1; however, the routine will appropriately \nhandle the situation where a(1) is not set to one. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: b (:) The numerator coefficients of the rational transfer function. real(kind=real64), intent(in) :: a (:) The denominator coefficients of the ration transfer function.  In \nthe case of an FIR filter, this parameter should be set to a \none-element array with a value of one.  Regardless, the value of\na(1) must be non-zero. real(kind=real64), intent(in) :: x (:) An N-element array containing the signal to filter. real(kind=real64), intent(in), optional, target :: delays (:) An optional array of length MAX(size(a), size(b)) - 1 that provides \nthe initial conditions for filter delays, and on ouput, the final \nconditions for filter delays. Return Value real(kind=real64), allocatable, (:) An N-element array containing the filtered signal.","tags":"","loc":"proc\\filter.html"},{"title":"gaussian_filter – SPECTRUM","text":"public pure function gaussian_filter(x, alpha, k) result(rst) Applies a Gaussian filter to a signal. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) An N-element array containing the signal to filter. real(kind=real64), intent(in) :: alpha A parameter that specifies the number of standard deviations desired in the kernel.  This parameter is related to the \nstandard deviation by . integer(kind=int32), intent(in) :: k The kernel size.  This value must be a positive, non-zero\ninteger value less than N. Return Value real(kind=real64), allocatable, (:) An N-element array containing the filtered signal.","tags":"","loc":"proc\\gaussian_filter.html"},{"title":"moving_average_filter – SPECTRUM","text":"public pure function moving_average_filter(navg, x) result(rst) Applies a moving average filter to a signal. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: navg The size of the averaging window.  This parameter must be positive\nand non-zero. real(kind=real64), intent(in) :: x (:) An N-element array containing the signal to filter. Return Value real(kind=real64), allocatable, (:) An N-element array containing the filtered signal.","tags":"","loc":"proc\\moving_average_filter.html"},{"title":"sinc_filter – SPECTRUM","text":"public pure function sinc_filter(fc, fs, x, fc2, ftype) result(rst) Applies a sinc-in-time filter (rectangular frequency response). Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: fc The filter cutoff frequency, in Hz. real(kind=real64), intent(in) :: fs The sampling frequency, in Hz. real(kind=real64), intent(in), dimension(:) :: x The signal to filter. real(kind=real64), intent(in), optional :: fc2 The second cutoff frequency for band-pass and band-stop filters. integer(kind=int32), intent(in), optional :: ftype The filter type.  This parameter must be one of the following values: LOW_PASS_FILTER: Denotes a low-pass filter. HIGH_PASS_FILTER: Denotes a high-pass filter. BAND_PASS_FILTER: Denotes a band-pass filter. BAND_STOP_FILTER: Denotes a band-stop filter. The default value is LOW_PASS_FILTER. Return Value real(kind=real64), allocatable, dimension(:) The filtered signal.","tags":"","loc":"proc\\sinc_filter.html"},{"title":"tv_filter – SPECTRUM","text":"public pure function tv_filter(x, lambda, niter) result(rst) Applies a total-variation filter to a signal. The algorithm used by this routine is based upon the algorithm presented \nby [Selesnick and Bayram]\n(https://eeweb.engineering.nyu.edu/iselesni/lecture_notes/TV_filtering.pdf). Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) An N-element array containing the signal to filter. real(kind=real64), intent(in) :: lambda The regularization parameter.  The actual value to use\nis problem dependent, but the noisier the data, the larger this value\nshould be.  A good starting point is typically 0.3 - 0.5; however, the\nactual value is problem dependent. integer(kind=int32), intent(in), optional :: niter An optional parameter controlling the number of iterations performed.\nThe default limit is 10 iterations. Return Value real(kind=real64), allocatable, (:) An N-element array containing the filtered signal.","tags":"","loc":"proc\\tv_filter.html"},{"title":"downsample – SPECTRUM","text":"public pure function downsample(n, fs, x) result(rst) Downsamples an evenly sampled signal by the specified factor. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The downsample factor.  The value must be non-zer and positive\nvalued. real(kind=real64), intent(in) :: fs The original signal sample rate, in Hz. real(kind=real64), intent(in), dimension(:) :: x The signal to downsample. Return Value real(kind=real64), allocatable, dimension(:) The downsampled signal.","tags":"","loc":"proc\\downsample.html"},{"title":"upsample – SPECTRUM","text":"public pure function upsample(n, fs, x) result(rst) Upsamples an evenly sampled signal by the specified factor. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The upsample factor.  This value must be non-zero and positive \nvalued. real(kind=real64), intent(in) :: fs The original signal sample rate, in Hz. real(kind=real64), intent(in), dimension(:) :: x The signal to upsample. Return Value real(kind=real64), allocatable, dimension(:) The upsampled signal.","tags":"","loc":"proc\\upsample.html"},{"title":"filter_frequency_response – SPECTRUM","text":"public pure function filter_frequency_response(b, a, f, fs) result(rst) Computes the complex frequency response of a rational filter. The coefficient ordering is the same as filter : and where . The returned values are \ntherefore at each requested frequency. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: b (:) The numerator coefficients of the rational transfer function. real(kind=real64), intent(in) :: a (:) The denominator coefficients of the rational transfer function. real(kind=real64), intent(in) :: f (:) The frequencies at which to evaluate the response, in Hz. real(kind=real64), intent(in) :: fs The sampling frequency, in Hz. Return Value complex(kind=real64), allocatable, (:) The complex frequency response at each frequency in f.","tags":"","loc":"proc\\filter_frequency_response.html"},{"title":"design_fir_filter – SPECTRUM","text":"public pure subroutine design_fir_filter(n, fc, fs, b, a, fc2, ftype) Designs a Hamming-windowed, linear-phase FIR filter. The returned coefficients use the same convention as filter: b contains\nthe numerator coefficients in increasing delay order and a is [1.0]. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The requested number of taps. Even values are increased by one. real(kind=real64), intent(in) :: fc The first cutoff frequency, in Hz. real(kind=real64), intent(in) :: fs The sampling frequency, in Hz. real(kind=real64), intent(out), allocatable :: b (:) The numerator coefficients of the designed filter. real(kind=real64), intent(out), allocatable :: a (:) The denominator coefficients. This is always [1.0]. real(kind=real64), intent(in), optional :: fc2 The second cutoff frequency for band-pass and band-stop filters. integer(kind=int32), intent(in), optional :: ftype The filter type. The default is LOW_PASS_FILTER.","tags":"","loc":"proc\\design_fir_filter.html"},{"title":"design_iir_filter – SPECTRUM","text":"public pure subroutine design_iir_filter(n, fc, fs, b, a, ftype) Designs an nth-order Butterworth IIR low-pass or high-pass filter. The returned coefficients are normalized such that a(1) is one and use\nthe increasing-delay convention required by filter. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The Butterworth filter order. real(kind=real64), intent(in) :: fc The cutoff frequency, in Hz. real(kind=real64), intent(in) :: fs The sampling frequency, in Hz. real(kind=real64), intent(out), allocatable :: b (:) The numerator coefficients of the designed filter. real(kind=real64), intent(out), allocatable :: a (:) The denominator coefficients of the designed filter. integer(kind=int32), intent(in), optional :: ftype LOW_PASS_FILTER (default) or HIGH_PASS_FILTER.","tags":"","loc":"proc\\design_iir_filter.html"},{"title":"cross_periodogram – SPECTRUM","text":"public pure function cross_periodogram(win, x, y, fs, nfft) result(rst) Computes the cross-spectral periodogram of two signals. Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window to apply.  The size of the window must be non-zero and \npositive-valued. real(kind=real64), intent(in) :: x (:) The first N-element signal to transform. real(kind=real64), intent(in) :: y (:) The second N-element signal to transform. real(kind=real64), intent(in), optional :: fs An optional input, that if supplied, allows for normalization of \nthe computed spectrum by the frequency resolution. integer(kind=int32), intent(in), optional :: nfft An optional input that can be used to force the length of each\nindividual DFT operation by padding any remaining space with zeros.\nIf not supplied, the window size is used to determine the size of\nthe DFT. Return Value complex(kind=real64), allocatable, (:) An array containing the discrete cross periodogram estimate.  The \nestimate is returned at discrete frequency intervals that can be \ndetermined by a call to frequency_bin_width.","tags":"","loc":"proc\\cross_periodogram.html"},{"title":"csd – SPECTRUM","text":"public pure function csd(win, x, y, fs, nfft) result(rst) Computes the cross spectral density (CSD) of a signal via Welch's\nmethod (sometimes referred to as cross power spectral density\nor CPSD). References Welch, P.D. \"The Use of Fast Fourier Transform for the Estimation of \n Power Spectra: A Method Based on Time Averaging Over Short, Modified \n Periodograms.\" IEEE Transactions on Audio and Electroacoustics, \n AU-15 (2): 70-73, 1967. Wikipedia - Welch's Method Wikipedia - Cross Power Spectral Density Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window to apply.  The size of the window must be non-zero and \npositive-valued. real(kind=real64), intent(in) :: x (:) The first N-element signal to transform. real(kind=real64), intent(in) :: y (:) The second N-element signal to transform. real(kind=real64), intent(in), optional :: fs An optional input, that if supplied, allows for normalization of \nthe computed spectrum by the frequency resolution. integer(kind=int32), intent(in), optional :: nfft An optional input that can be used to force the length of each\nindividual DFT operation by padding any remaining space with zeros.\nIf not supplied, the window size is used to determine the size of\nthe DFT. Return Value complex(kind=real64), allocatable, (:) An array containing the discrete CSD estimate.  The estimate is\nreturned at discrete frequency intervals that can be determined by\na call to frequency_bin_width.","tags":"","loc":"proc\\csd.html"},{"title":"periodogram – SPECTRUM","text":"public pure function periodogram(win, x, fs, nfft) result(rst) Computes the periodogram of a signal. Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window to apply.  The size of the window must be non-zero and \npositive-valued. real(kind=real64), intent(in) :: x (:) The signal to transform. real(kind=real64), intent(in), optional :: fs An optional input, that if supplied, allows for normalization of \nthe computed spectrum by the frequency resolution. integer(kind=int32), intent(in), optional :: nfft An optional input that can be used to force the length of each\nindividual DFT operation by padding any remaining space with zeros.\nIf not supplied, the window size is used to determine the size of\nthe DFT. Return Value real(kind=real64), allocatable, (:) An array containing the discrete PSD estimate.  The estimate is\nreturned at discrete frequency intervals that can be determined by\na call to frequency_bin_width.","tags":"","loc":"proc\\periodogram.html"},{"title":"psd – SPECTRUM","text":"public pure function psd(win, x, fs, nfft) result(rst) Computes the power spectral density (PSD) of a signal via Welch's\nmethod. References Welch, P.D. \"The Use of Fast Fourier Transform for the Estimation of \n Power Spectra: A Method Based on Time Averaging Over Short, Modified \n Periodograms.\" IEEE Transactions on Audio and Electroacoustics, \n AU-15 (2): 70-73, 1967. Wikipedia - Welch's Method Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window to apply.  The size of the window must be non-zero and \npositive-valued. real(kind=real64), intent(in) :: x (:) The signal to transform. real(kind=real64), intent(in), optional :: fs An optional input, that if supplied, allows for normalization of \nthe computed spectrum by the frequency resolution. integer(kind=int32), intent(in), optional :: nfft An optional input that can be used to force the length of each\nindividual DFT operation by padding any remaining space with zeros.\nIf not supplied, the window size is used to determine the size of\nthe DFT. Return Value real(kind=real64), allocatable, (:) An array containing the discrete PSD estimate.  The estimate is\nreturned at discrete frequency intervals that can be determined by\na call to frequency_bin_width.","tags":"","loc":"proc\\psd.html"},{"title":"compute_overlap_segment_count – SPECTRUM","text":"public pure function compute_overlap_segment_count(n, winsize) result(rst) Computes the number of overlapped signals using a nominal 50% overlap. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The total length of the signal being overlapped. integer(kind=int32), intent(in) :: winsize The window size. Return Value integer(kind=int32) The number of segments.","tags":"","loc":"proc\\compute_overlap_segment_count.html"},{"title":"compute_transform_length – SPECTRUM","text":"public pure function compute_transform_length(n) result(rst) Computes the length of the positive half of a discrete Fourier\ntransform for a specific signal length. The length of the discrete Fourier transform is determined as follows. If n is even, else; . Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The signal length (length of the signal put forth to the Fourier \ntransform). Return Value integer(kind=int32) The length of the positive half of the discrete Fourier transform.","tags":"","loc":"proc\\compute_transform_length.html"},{"title":"cumulative_sum – SPECTRUM","text":"public pure function cumulative_sum(x) result(rst) Computes the cumulative sum of an array. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) The N-element array on which to operate. Return Value real(kind=real64), allocatable, (:) An N-element array containing the cumulative sum of each element\nin x (e.g. cumulative_sum(x) = [x(1), x(1) + x(2), ...]).","tags":"","loc":"proc\\cumulative_sum.html"},{"title":"difference – SPECTRUM","text":"public pure function difference(x) result(rst) Computes the difference between each element in an array. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) The N-element array on which to operate. Return Value real(kind=real64), allocatable, (:) The N-1 element array containing the difference between each element\nin x.","tags":"","loc":"proc\\difference.html"},{"title":"frequency_bin_width – SPECTRUM","text":"public pure elemental function frequency_bin_width(fs, n) result(rst) Computes the bin width for a discrete frequency spectrum based\nupon the data sample rate. The frequency bin width is computed as follows. where m is computed via compute_transform_length. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: fs The rate at which the signal was sampled.  The units of this value \nwill be the units of the output. integer(kind=int32), intent(in) :: n The signal length (length of the signal put forth to the\nFourier transform). Return Value real(kind=real64) The frequency bin width.","tags":"","loc":"proc\\frequency_bin_width.html"},{"title":"is_power_of_two – SPECTRUM","text":"public pure elemental function is_power_of_two(n) result(rst) Tests to see if a value is an integer power of two. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The value to test. Return Value logical Returns true if n is a power of two; else, false.","tags":"","loc":"proc\\is_power_of_two.html"},{"title":"next_power_of_two – SPECTRUM","text":"public pure elemental function next_power_of_two(n) result(rst) Provides the next higher integer power of two. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The value to test. Return Value integer(kind=int32) The next power of two higher than n.  If n is already a power of two,\nits value is simply returned.  For instance, if n is set to 128, \nthen a value of 7 is returned ( ).","tags":"","loc":"proc\\next_power_of_two.html"},{"title":"remove_mean – SPECTRUM","text":"public pure function remove_mean(x) result(rst) Removes the mean offset from the specified data set. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in), dimension(:) :: x The array on which to operate. Return Value real(kind=real64), allocatable, dimension(:) The data set with its mean removed.","tags":"","loc":"proc\\remove_mean.html"},{"title":"unpack_real_transform – SPECTRUM","text":"public pure function unpack_real_transform(x, fac) result(rst) Unpacks a real-valued transform into its complex-valued format. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) The complex-valued signal stored in a real-valued array.  This array\nis assumed to be of length N. real(kind=real64), intent(in), optional :: fac An optional scaling input.  The default is 1 such that no scaling\nis performed. Return Value complex(kind=real64), allocatable, dimension(:) The unpacked complex-valued form of the input array.","tags":"","loc":"proc\\unpack_real_transform.html"},{"title":"overlap – SPECTRUM","text":"public pure subroutine overlap(x, seg, winsize, buffer) Extracts a segment from a signal allowing for a nominally 50% overlap. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) An N-element array containing the entire signal. integer(kind=int32), intent(in) :: seg The one-based index of the segment to extract. integer(kind=int32), intent(in) :: winsize The size of the window (segment).  If this value is less than N, the \nend of the segment will be padded with zeros. real(kind=real64), intent(out) :: buffer (:) A winsize array where the segment will be written.","tags":"","loc":"proc\\overlap.html"},{"title":"unwrap – SPECTRUM","text":"public  subroutine unwrap(x, tol) Shifts phase angle arrays to deal with jumps greater than or equal\nto tol by adding multiples of until\nthe jump is less than tol. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(inout) :: x (:) On input, the phase array.  On output, the unwrapped phase array. real(kind=real64), intent(in), optional :: tol The tolerance value.","tags":"","loc":"proc\\unwrap.html"},{"title":"mimo_transfer_function – SPECTRUM","text":"public pure function mimo_transfer_function(win, x, y, etype, nfft) result(rst) Estimates the transfer function matrix for a multiple-input/\nmultiple-output (MIMO) system. The input signal matrix is expected to have dimensions (n, nin) where\nthe second index denotes the input channel.  The output signal matrix is\nexpected to have dimensions (n, nout) where the second index denotes the\noutput channel.  The returned transfer matrix has dimensions\n(nout, nin, m) where m is the transform length. Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window object. real(kind=real64), intent(in) :: x (:,:) An N-by-NIN array containing the input signals. real(kind=real64), intent(in) :: y (:,:) An N-by-NOUT array containing the output signals. integer(kind=int32), intent(in), optional :: etype An optional input that, if supplied, denotes the estimator to use.\nSupported values are the same as for SISO transfer estimates. integer(kind=int32), intent(in), optional :: nfft An optional input that can be used to force the length of each\nindividual DFT operation by padding any remaining space with zeros. Return Value complex(kind=real64), allocatable, (:,:,:) Returns the complex-valued transfer function estimate matrix.","tags":"","loc":"proc\\mimo_transfer_function.html"},{"title":"siso_transfer_function – SPECTRUM","text":"public pure function siso_transfer_function(win, x, y, etype, nfft) result(rst) Estimates the transfer function for a single-input/single-output\n(SISO) system. Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window object. real(kind=real64), intent(in) :: x (:) An N-element array containing the input signal. real(kind=real64), intent(in) :: y (:) An N-element array containing the output signal. integer(kind=int32), intent(in), optional :: etype An optional input that, if supplied, denotes the\nestimator to use.  If no value is specified, an H1 estimator is used.\nThe following options are supported. SPCTRM_H1_ESTIMATOR: Uses an H1 estimate. SPCTRM_H2_ESTIMATOR: Uses an H2 estimate. If an unrecognized value is provided, the routine defaults to an \nH1 estimator. integer(kind=int32), intent(in), optional :: nfft An optional input that can be used to force the length of each\nindividual DFT operation by padding any remaining space with zeros.\nIf not supplied, the window size is used to determine the size of\nthe DFT. Return Value complex(kind=real64), allocatable, (:) Returns the complex-valued transfer function estimate.","tags":"","loc":"proc\\siso_transfer_function.html"},{"title":"window_function – SPECTRUM","text":"interface public pure function window_function(this, bin) result(rst) Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: this The window object. integer(kind=int32), intent(in) :: bin The index or bin number [0, n], where n is the window size. Return Value real(kind=real64) The function value. Description Evaluates the window function.","tags":"","loc":"interface\\window_function.html"},{"title":"filter_diff – SPECTRUM","text":"public pure function filter_diff(dt, x, fc) result(rst) Estimates the derivative of a signal by utilization of a second-order\nsystem as a filter. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: dt The time step between data points. real(kind=real64), intent(in), dimension(:) :: x An N-element array containing the data whose derivative is to be \nestimated. real(kind=real64), intent(in) :: fc The filter cutoff frequency, in Hz. Return Value real(kind=real64), allocatable, dimension(:,:) An N-element array containing the filtered signal in the first column\nand the derivative estimate in the second.","tags":"","loc":"proc\\filter_diff.html"},{"title":"stencil_diff_5 – SPECTRUM","text":"public pure function stencil_diff_5(dt, x) result(rst) Utilizes a 5-point stencil to estimate the derivative of a data set. See Also Wikipedia Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: dt The time step between data points. real(kind=real64), intent(in), dimension(:) :: x An N-element array containing the data whose derivative is to be \nestimated. Return Value real(kind=real64), allocatable, dimension(:) An N-element array containing the derivative estimate.","tags":"","loc":"proc\\stencil_diff_5.html"},{"title":"stencil_second_diff_5 – SPECTRUM","text":"public pure function stencil_second_diff_5(dt, x) result(rst) Utilizes a 5-point stencil to estimate the second derivative of a data\nset. See Also Wikipedia Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: dt The time step between data points. real(kind=real64), intent(in), dimension(:) :: x An N-element array containing the data whose derivative is to be \nestimated. Return Value real(kind=real64), allocatable, dimension(:) An N-element array containing the derivative estimate.","tags":"","loc":"proc\\stencil_second_diff_5.html"},{"title":"tvr_derivative – SPECTRUM","text":"public  function tvr_derivative(dt, x, alpha, maxiter, tol, use_sparse, niter) result(rst) Computes an estimate to the derivative of an evenly-sampled data\nset using total variation regularization. This implementation solves the augmented dense formulation using an\nintegration matrix and a first-difference regularization operator. The\ndense formulation uses the physical time step in its difference matrix\nand allocates dense matrices whose storage grows quadratically with the\nnumber of samples. When use_sparse is true, this routine dispatches to\ntvr_derivative_sparse. That solver uses a different data-fitting term,\na second-difference operator, physical curvature scaling, and normalized\nIRLS weights. Consequently, alpha values are solver-specific and should\nnot be compared directly. See Also van Breugel, Floris & Brunton, Bingni & Kutz, J.. (2020). Numerical \n  differentiation of noisy data: A unifying multi-objective optimization \n  framework. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: dt The time step between data points. real(kind=real64), intent(in), dimension(:) :: x An N-element array containing the data whose derivative is\nto be estimated. real(kind=real64), intent(in) :: alpha The regularization parameter. integer(kind=int32), intent(in), optional :: maxiter The maximum number of iterations to allow.  The default is 20 \niterations. real(kind=real64), intent(in), optional :: tol The convergence tolerance to use.  The tolerance is \napplied to the change in the update measure. The dense solver uses\nan absolute Euclidean norm, while the sparse solver uses a relative\nEuclidean norm. The default is 1e-3. logical, intent(in), optional :: use_sparse True if the sparse solver should be used vs. the dense solver.  This \nis highly recommended when N is larger than ~1000.  The default is \ntrue such that the sparse solver is used. The sparse solver has\nlinear storage growth and is preferred for large data sets. integer(kind=int32), intent(out), optional :: niter The number of iterations actually performed. Return Value real(kind=real64), allocatable, dimension(:) An N-element array containing the estimate of the derivative.","tags":"","loc":"proc\\tvr_derivative.html"},{"title":"finite_difference – SPECTRUM","text":"public interface finite_difference Module Procedures private pure function finite_difference_1(dt, x) result(rst) Estimates the derivative of a data set by means of a naive \nimplementation of a finite difference scheme based upon central \ndifferences. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: dt The time step between data points. real(kind=real64), intent(in), dimension(:) :: x An N-element array containing the data whose derivative is to be \nestimated. Return Value real(kind=real64), allocatable, dimension(:) An N-element array containing the derivative estimate. private pure function finite_difference_2(t, x) result(rst) Computes an estimate to the derivative of an evenly-sampled data\nset using total variation regularization. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in), dimension(:) :: t An N-element array containing the time points at which x was sampled. real(kind=real64), intent(in), dimension(:) :: x An N-element array containing the data whose derivative is to be \nestimated. Return Value real(kind=real64), allocatable, dimension(:) An N-element array containing the derivative estimate.","tags":"","loc":"interface\\finite_difference.html"},{"title":"convolve – SPECTRUM","text":"public pure function convolve(x, y, method) result(rst) Computes the convolution of a signal and kernel. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) The N-element signal. real(kind=real64), intent(in) :: y (:) The M-element kernel. integer(kind=int32), intent(in), optional :: method An optional input that dictates the expected\nconvolution result.  The following options are available. SPCTRM_FULL_CONVOLUTION: The full convolution results are provided, \n    including the portions polluted courtesy of the zero-padding and\n    the corresponding wrap-around effects.  The length of this output\n    is N + M - 1. SPCTRM_CENTRAL_CONVOLUTION: The N-element result containing the \n    convolved signal not poluted by the zero-padding and \n    corresponding wrap-around effects. Return Value real(kind=real64), allocatable, (:) The convolved result.","tags":"","loc":"proc\\convolve.html"},{"title":"spectrum_integrate – SPECTRUM","text":"Uses iso_fortran_env Functions public pure function integrate (dt, x, iv) result(rst) Integrates a data set. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: dt The sample interval. real(kind=real64), intent(in), dimension(:) :: x The data set to integrate. real(kind=real64), intent(in), optional :: iv The initial value.  The default value is zero. Return Value real(kind=real64), allocatable, dimension(:) The integrated data set.","tags":"","loc":"module\\spectrum_integrate.html"},{"title":"spectrum – SPECTRUM","text":"Uses spectrum_fft spectrum_resample spectrum_filter spectrum_integrate spectrum_diff fftpack spectrum_filter_design spectrum_tf spectrum_periodogram spectrum_routines spectrum_windows spectrum_convolve","tags":"","loc":"module\\spectrum.html"},{"title":"spectrum_fft – SPECTRUM","text":"Uses spectrum_routines iso_fortran_env spectrum_windows fftpack Derived Types type, public :: stft_result A container for STFT output. Components Type Visibility Attributes Name Initial integer(kind=int32), public, allocatable, dimension(:) :: offsets The starting indices of each window segment. complex(kind=real64), public, allocatable, dimension(:,:) :: stft An M-by-N matrix containing the M-element complex-valued \ntransforms for each of the N time points studied.  M is the \nsize of the positive half of the transform, and N is the total \nnumber of transformed segments. Functions public pure function irfft (x, n) result(rst) Computes the inverse Fourier transform for a real-valued data set. Arguments Type Intent Optional Attributes Name complex(kind=real64), intent(in), dimension(:) :: x The positive half of the transform. integer(kind=int32), intent(in), optional :: n An optional input that can be used to specify the length of the \ntransform.  If less than the length of x, x is truncated; however, \nif greater than the length of x, x is padded with zeros. Return Value real(kind=real64), allocatable, dimension(:) The real-valued result of the inverse transform. public pure function rfft (x, n) result(rst) Computes the Fourier transform of a real-valued data set.  Only the \npositive half of the transform is returned. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in), dimension(:) :: x The real-valued array to transform. integer(kind=int32), intent(in), optional :: n An optional input that can be used to specify the length of the \ntransform.  If less than the length of x, x is truncated; however, \nif greater than the length of x, x is padded with zeros. Return Value complex(kind=real64), allocatable, dimension(:) The complex-valued result of the transform. public pure function stft (win, x) result(rst) Computes the short time Fourier transform of a signal. Read more… Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window to apply. real(kind=real64), intent(in) :: x (:) The signal to analyze.  The signal must be longer than the size of \nthe window. Return Value type( stft_result ) A container filled with the transform results.","tags":"","loc":"module\\spectrum_fft.html"},{"title":"spectrum_filter – SPECTRUM","text":"Uses spectrum_routines iso_fortran_env spectrum_convolve fftpack Variables Type Visibility Attributes Name Initial integer(kind=int32), public, parameter :: BAND_PASS_FILTER = 3 Denotes a band-pass filter. integer(kind=int32), public, parameter :: BAND_STOP_FILTER = 4 Denotes a band-stop filter. integer(kind=int32), public, parameter :: HIGH_PASS_FILTER = 2 Denotes a high-pass filter. integer(kind=int32), public, parameter :: LOW_PASS_FILTER = 1 Denotes a low-pass filter. Functions public pure function filter (b, a, x, delays) result(rst) Applies the specified filter to a signal. Read more… Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: b (:) The numerator coefficients of the rational transfer function. real(kind=real64), intent(in) :: a (:) The denominator coefficients of the ration transfer function.  In \nthe case of an FIR filter, this parameter should be set to a \none-element array with a value of one.  Regardless, the value of\na(1) must be non-zero. real(kind=real64), intent(in) :: x (:) An N-element array containing the signal to filter. real(kind=real64), intent(in), optional, target :: delays (:) An optional array of length MAX(size(a), size(b)) - 1 that provides \nthe initial conditions for filter delays, and on ouput, the final \nconditions for filter delays. Return Value real(kind=real64), allocatable, (:) An N-element array containing the filtered signal. public pure function gaussian_filter (x, alpha, k) result(rst) Applies a Gaussian filter to a signal. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) An N-element array containing the signal to filter. real(kind=real64), intent(in) :: alpha A parameter that specifies the number of standard deviations desired in the kernel.  This parameter is related to the \nstandard deviation by . integer(kind=int32), intent(in) :: k The kernel size.  This value must be a positive, non-zero\ninteger value less than N. Return Value real(kind=real64), allocatable, (:) An N-element array containing the filtered signal. public pure function moving_average_filter (navg, x) result(rst) Applies a moving average filter to a signal. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: navg The size of the averaging window.  This parameter must be positive\nand non-zero. real(kind=real64), intent(in) :: x (:) An N-element array containing the signal to filter. Return Value real(kind=real64), allocatable, (:) An N-element array containing the filtered signal. public pure function sinc_filter (fc, fs, x, fc2, ftype) result(rst) Applies a sinc-in-time filter (rectangular frequency response). Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: fc The filter cutoff frequency, in Hz. real(kind=real64), intent(in) :: fs The sampling frequency, in Hz. real(kind=real64), intent(in), dimension(:) :: x The signal to filter. real(kind=real64), intent(in), optional :: fc2 The second cutoff frequency for band-pass and band-stop filters. integer(kind=int32), intent(in), optional :: ftype The filter type.  This parameter must be one of the following values: Read more… Return Value real(kind=real64), allocatable, dimension(:) The filtered signal. public pure function tv_filter (x, lambda, niter) result(rst) Applies a total-variation filter to a signal. Read more… Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) An N-element array containing the signal to filter. real(kind=real64), intent(in) :: lambda The regularization parameter.  The actual value to use\nis problem dependent, but the noisier the data, the larger this value\nshould be.  A good starting point is typically 0.3 - 0.5; however, the\nactual value is problem dependent. integer(kind=int32), intent(in), optional :: niter An optional parameter controlling the number of iterations performed.\nThe default limit is 10 iterations. Return Value real(kind=real64), allocatable, (:) An N-element array containing the filtered signal.","tags":"","loc":"module\\spectrum_filter.html"},{"title":"spectrum_resample – SPECTRUM","text":"Uses iso_fortran_env spectrum_filter Functions public pure function downsample (n, fs, x) result(rst) Downsamples an evenly sampled signal by the specified factor. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The downsample factor.  The value must be non-zer and positive\nvalued. real(kind=real64), intent(in) :: fs The original signal sample rate, in Hz. real(kind=real64), intent(in), dimension(:) :: x The signal to downsample. Return Value real(kind=real64), allocatable, dimension(:) The downsampled signal. public pure function upsample (n, fs, x) result(rst) Upsamples an evenly sampled signal by the specified factor. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The upsample factor.  This value must be non-zero and positive \nvalued. real(kind=real64), intent(in) :: fs The original signal sample rate, in Hz. real(kind=real64), intent(in), dimension(:) :: x The signal to upsample. Return Value real(kind=real64), allocatable, dimension(:) The upsampled signal.","tags":"","loc":"module\\spectrum_resample.html"},{"title":"spectrum_filter_design – SPECTRUM","text":"Uses iso_fortran_env spectrum_filter Functions public pure function filter_frequency_response (b, a, f, fs) result(rst) Computes the complex frequency response of a rational filter. Read more… Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: b (:) The numerator coefficients of the rational transfer function. real(kind=real64), intent(in) :: a (:) The denominator coefficients of the rational transfer function. real(kind=real64), intent(in) :: f (:) The frequencies at which to evaluate the response, in Hz. real(kind=real64), intent(in) :: fs The sampling frequency, in Hz. Return Value complex(kind=real64), allocatable, (:) The complex frequency response at each frequency in f. Subroutines public pure subroutine design_fir_filter (n, fc, fs, b, a, fc2, ftype) Designs a Hamming-windowed, linear-phase FIR filter. Read more… Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The requested number of taps. Even values are increased by one. real(kind=real64), intent(in) :: fc The first cutoff frequency, in Hz. real(kind=real64), intent(in) :: fs The sampling frequency, in Hz. real(kind=real64), intent(out), allocatable :: b (:) The numerator coefficients of the designed filter. real(kind=real64), intent(out), allocatable :: a (:) The denominator coefficients. This is always [1.0]. real(kind=real64), intent(in), optional :: fc2 The second cutoff frequency for band-pass and band-stop filters. integer(kind=int32), intent(in), optional :: ftype The filter type. The default is LOW_PASS_FILTER. public pure subroutine design_iir_filter (n, fc, fs, b, a, ftype) Designs an nth-order Butterworth IIR low-pass or high-pass filter. Read more… Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The Butterworth filter order. real(kind=real64), intent(in) :: fc The cutoff frequency, in Hz. real(kind=real64), intent(in) :: fs The sampling frequency, in Hz. real(kind=real64), intent(out), allocatable :: b (:) The numerator coefficients of the designed filter. real(kind=real64), intent(out), allocatable :: a (:) The denominator coefficients of the designed filter. integer(kind=int32), intent(in), optional :: ftype LOW_PASS_FILTER (default) or HIGH_PASS_FILTER.","tags":"","loc":"module\\spectrum_filter_design.html"},{"title":"spectrum_periodogram – SPECTRUM","text":"Uses spectrum_routines iso_fortran_env spectrum_windows fftpack Functions public pure function cross_periodogram (win, x, y, fs, nfft) result(rst) Computes the cross-spectral periodogram of two signals. Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window to apply.  The size of the window must be non-zero and \npositive-valued. real(kind=real64), intent(in) :: x (:) The first N-element signal to transform. real(kind=real64), intent(in) :: y (:) The second N-element signal to transform. real(kind=real64), intent(in), optional :: fs An optional input, that if supplied, allows for normalization of \nthe computed spectrum by the frequency resolution. integer(kind=int32), intent(in), optional :: nfft An optional input that can be used to force the length of each\nindividual DFT operation by padding any remaining space with zeros.\nIf not supplied, the window size is used to determine the size of\nthe DFT. Return Value complex(kind=real64), allocatable, (:) An array containing the discrete cross periodogram estimate.  The \nestimate is returned at discrete frequency intervals that can be \ndetermined by a call to frequency_bin_width. public pure function csd (win, x, y, fs, nfft) result(rst) Computes the cross spectral density (CSD) of a signal via Welch's\nmethod (sometimes referred to as cross power spectral density\nor CPSD). Read more… Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window to apply.  The size of the window must be non-zero and \npositive-valued. real(kind=real64), intent(in) :: x (:) The first N-element signal to transform. real(kind=real64), intent(in) :: y (:) The second N-element signal to transform. real(kind=real64), intent(in), optional :: fs An optional input, that if supplied, allows for normalization of \nthe computed spectrum by the frequency resolution. integer(kind=int32), intent(in), optional :: nfft An optional input that can be used to force the length of each\nindividual DFT operation by padding any remaining space with zeros.\nIf not supplied, the window size is used to determine the size of\nthe DFT. Return Value complex(kind=real64), allocatable, (:) An array containing the discrete CSD estimate.  The estimate is\nreturned at discrete frequency intervals that can be determined by\na call to frequency_bin_width. public pure function periodogram (win, x, fs, nfft) result(rst) Computes the periodogram of a signal. Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window to apply.  The size of the window must be non-zero and \npositive-valued. real(kind=real64), intent(in) :: x (:) The signal to transform. real(kind=real64), intent(in), optional :: fs An optional input, that if supplied, allows for normalization of \nthe computed spectrum by the frequency resolution. integer(kind=int32), intent(in), optional :: nfft An optional input that can be used to force the length of each\nindividual DFT operation by padding any remaining space with zeros.\nIf not supplied, the window size is used to determine the size of\nthe DFT. Return Value real(kind=real64), allocatable, (:) An array containing the discrete PSD estimate.  The estimate is\nreturned at discrete frequency intervals that can be determined by\na call to frequency_bin_width. public pure function psd (win, x, fs, nfft) result(rst) Computes the power spectral density (PSD) of a signal via Welch's\nmethod. Read more… Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window to apply.  The size of the window must be non-zero and \npositive-valued. real(kind=real64), intent(in) :: x (:) The signal to transform. real(kind=real64), intent(in), optional :: fs An optional input, that if supplied, allows for normalization of \nthe computed spectrum by the frequency resolution. integer(kind=int32), intent(in), optional :: nfft An optional input that can be used to force the length of each\nindividual DFT operation by padding any remaining space with zeros.\nIf not supplied, the window size is used to determine the size of\nthe DFT. Return Value real(kind=real64), allocatable, (:) An array containing the discrete PSD estimate.  The estimate is\nreturned at discrete frequency intervals that can be determined by\na call to frequency_bin_width.","tags":"","loc":"module\\spectrum_periodogram.html"},{"title":"spectrum_routines – SPECTRUM","text":"Uses iso_fortran_env fftpack Functions public pure function compute_overlap_segment_count (n, winsize) result(rst) Computes the number of overlapped signals using a nominal 50% overlap. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The total length of the signal being overlapped. integer(kind=int32), intent(in) :: winsize The window size. Return Value integer(kind=int32) The number of segments. public pure function compute_transform_length (n) result(rst) Computes the length of the positive half of a discrete Fourier\ntransform for a specific signal length. Read more… Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The signal length (length of the signal put forth to the Fourier \ntransform). Return Value integer(kind=int32) The length of the positive half of the discrete Fourier transform. public pure function cumulative_sum (x) result(rst) Computes the cumulative sum of an array. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) The N-element array on which to operate. Return Value real(kind=real64), allocatable, (:) An N-element array containing the cumulative sum of each element\nin x (e.g. cumulative_sum(x) = [x(1), x(1) + x(2), ...]). public pure function difference (x) result(rst) Computes the difference between each element in an array. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) The N-element array on which to operate. Return Value real(kind=real64), allocatable, (:) The N-1 element array containing the difference between each element\nin x. public pure elemental function frequency_bin_width (fs, n) result(rst) Computes the bin width for a discrete frequency spectrum based\nupon the data sample rate. Read more… Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: fs The rate at which the signal was sampled.  The units of this value \nwill be the units of the output. integer(kind=int32), intent(in) :: n The signal length (length of the signal put forth to the\nFourier transform). Return Value real(kind=real64) The frequency bin width. public pure elemental function is_power_of_two (n) result(rst) Tests to see if a value is an integer power of two. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The value to test. Return Value logical Returns true if n is a power of two; else, false. public pure elemental function next_power_of_two (n) result(rst) Provides the next higher integer power of two. Arguments Type Intent Optional Attributes Name integer(kind=int32), intent(in) :: n The value to test. Return Value integer(kind=int32) The next power of two higher than n.  If n is already a power of two,\nits value is simply returned.  For instance, if n is set to 128, \nthen a value of 7 is returned ( ). public pure function remove_mean (x) result(rst) Removes the mean offset from the specified data set. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in), dimension(:) :: x The array on which to operate. Return Value real(kind=real64), allocatable, dimension(:) The data set with its mean removed. public pure function unpack_real_transform (x, fac) result(rst) Unpacks a real-valued transform into its complex-valued format. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) The complex-valued signal stored in a real-valued array.  This array\nis assumed to be of length N. real(kind=real64), intent(in), optional :: fac An optional scaling input.  The default is 1 such that no scaling\nis performed. Return Value complex(kind=real64), allocatable, dimension(:) The unpacked complex-valued form of the input array. Subroutines public pure subroutine overlap (x, seg, winsize, buffer) Extracts a segment from a signal allowing for a nominally 50% overlap. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) An N-element array containing the entire signal. integer(kind=int32), intent(in) :: seg The one-based index of the segment to extract. integer(kind=int32), intent(in) :: winsize The size of the window (segment).  If this value is less than N, the \nend of the segment will be padded with zeros. real(kind=real64), intent(out) :: buffer (:) A winsize array where the segment will be written. public  subroutine unwrap (x, tol) Shifts phase angle arrays to deal with jumps greater than or equal\nto tol by adding multiples of until\nthe jump is less than tol. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(inout) :: x (:) On input, the phase array.  On output, the unwrapped phase array. real(kind=real64), intent(in), optional :: tol The tolerance value.","tags":"","loc":"module\\spectrum_routines.html"},{"title":"spectrum_tf – SPECTRUM","text":"Uses spectrum_windows iso_fortran_env spectrum_periodogram spectrum_routines Variables Type Visibility Attributes Name Initial integer(kind=int32), public, parameter :: SPCTRM_H1_ESTIMATOR = 50002 A flag for requesting an H1 transfer function estimator.  An H1 \nestimator is best used when noise is uncorrelated with the input, \nand results in a transfer function estimate of the form . integer(kind=int32), public, parameter :: SPCTRM_H2_ESTIMATOR = 50003 A flag for requesting an H2 transfer function estimator.  An H2 \nestimator is best used when noise is uncorrelated with the output, \nand results in a transfer function estimate of the form . Functions public pure function mimo_transfer_function (win, x, y, etype, nfft) result(rst) Estimates the transfer function matrix for a multiple-input/\nmultiple-output (MIMO) system. Read more… Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window object. real(kind=real64), intent(in) :: x (:,:) An N-by-NIN array containing the input signals. real(kind=real64), intent(in) :: y (:,:) An N-by-NOUT array containing the output signals. integer(kind=int32), intent(in), optional :: etype An optional input that, if supplied, denotes the estimator to use.\nSupported values are the same as for SISO transfer estimates. integer(kind=int32), intent(in), optional :: nfft An optional input that can be used to force the length of each\nindividual DFT operation by padding any remaining space with zeros. Return Value complex(kind=real64), allocatable, (:,:,:) Returns the complex-valued transfer function estimate matrix. public pure function siso_transfer_function (win, x, y, etype, nfft) result(rst) Estimates the transfer function for a single-input/single-output\n(SISO) system. Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: win The window object. real(kind=real64), intent(in) :: x (:) An N-element array containing the input signal. real(kind=real64), intent(in) :: y (:) An N-element array containing the output signal. integer(kind=int32), intent(in), optional :: etype An optional input that, if supplied, denotes the\nestimator to use.  If no value is specified, an H1 estimator is used.\nThe following options are supported. Read more… integer(kind=int32), intent(in), optional :: nfft An optional input that can be used to force the length of each\nindividual DFT operation by padding any remaining space with zeros.\nIf not supplied, the window size is used to determine the size of\nthe DFT. Return Value complex(kind=real64), allocatable, (:) Returns the complex-valued transfer function estimate.","tags":"","loc":"module\\spectrum_tf.html"},{"title":"spectrum_windows – SPECTRUM","text":"Uses iso_fortran_env Interfaces interface public pure function window_function(this, bin) result(rst) Evaluates the window function. Arguments Type Intent Optional Attributes Name class( window ), intent(in) :: this The window object. integer(kind=int32), intent(in) :: bin The index or bin number [0, n], where n is the window size. Return Value real(kind=real64) The function value. Derived Types type, public, extends( window ) :: blackman_harris_window Defines a Blackman-Harris window. Read more… Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure, public :: evaluate => bhw_eval type, public, extends( window ) :: flat_top_window Defines a flat-top window. Read more… Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure, public :: evaluate => ftw_eval type, public, extends( window ) :: hamming_window Defines a Hamming window. Read more… Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure, public :: evaluate => hamming_eval type, public, extends( window ) :: hann_window Defines a Hann window. Read more… Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure, public :: evaluate => hann_eval type, public, extends( window ) :: rectangular_window @brief Defines a rectangular window.\nDefines a rectangular window. Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure, public :: evaluate => rw_eval type, public, extends( window ) :: welch_window Defines a Welch window. Read more… Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure, public :: evaluate => welch_eval type, public :: window Defines the structure of a window. Components Type Visibility Attributes Name Initial integer(kind=int32), public :: size = 0 The window size. Type-Bound Procedures procedure( window_function ), public, deferred, pass :: evaluate","tags":"","loc":"module\\spectrum_windows.html"},{"title":"spectrum_diff – SPECTRUM","text":"Uses lapack iso_fortran_env linalg blas Interfaces public        interface finite_difference private pure function finite_difference_1(dt, x) result(rst) Estimates the derivative of a data set by means of a naive \nimplementation of a finite difference scheme based upon central \ndifferences. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: dt The time step between data points. real(kind=real64), intent(in), dimension(:) :: x An N-element array containing the data whose derivative is to be \nestimated. Return Value real(kind=real64), allocatable, dimension(:) An N-element array containing the derivative estimate. private pure function finite_difference_2(t, x) result(rst) Computes an estimate to the derivative of an evenly-sampled data\nset using total variation regularization. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in), dimension(:) :: t An N-element array containing the time points at which x was sampled. real(kind=real64), intent(in), dimension(:) :: x An N-element array containing the data whose derivative is to be \nestimated. Return Value real(kind=real64), allocatable, dimension(:) An N-element array containing the derivative estimate. Functions public pure function filter_diff (dt, x, fc) result(rst) Estimates the derivative of a signal by utilization of a second-order\nsystem as a filter. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: dt The time step between data points. real(kind=real64), intent(in), dimension(:) :: x An N-element array containing the data whose derivative is to be \nestimated. real(kind=real64), intent(in) :: fc The filter cutoff frequency, in Hz. Return Value real(kind=real64), allocatable, dimension(:,:) An N-element array containing the filtered signal in the first column\nand the derivative estimate in the second. public pure function stencil_diff_5 (dt, x) result(rst) Utilizes a 5-point stencil to estimate the derivative of a data set. Read more… Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: dt The time step between data points. real(kind=real64), intent(in), dimension(:) :: x An N-element array containing the data whose derivative is to be \nestimated. Return Value real(kind=real64), allocatable, dimension(:) An N-element array containing the derivative estimate. public pure function stencil_second_diff_5 (dt, x) result(rst) Utilizes a 5-point stencil to estimate the second derivative of a data\nset. Read more… Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: dt The time step between data points. real(kind=real64), intent(in), dimension(:) :: x An N-element array containing the data whose derivative is to be \nestimated. Return Value real(kind=real64), allocatable, dimension(:) An N-element array containing the derivative estimate. public  function tvr_derivative (dt, x, alpha, maxiter, tol, use_sparse, niter) result(rst) Computes an estimate to the derivative of an evenly-sampled data\nset using total variation regularization. Read more… Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: dt The time step between data points. real(kind=real64), intent(in), dimension(:) :: x An N-element array containing the data whose derivative is\nto be estimated. real(kind=real64), intent(in) :: alpha The regularization parameter. integer(kind=int32), intent(in), optional :: maxiter The maximum number of iterations to allow.  The default is 20 \niterations. real(kind=real64), intent(in), optional :: tol The convergence tolerance to use.  The tolerance is \napplied to the change in the update measure. The dense solver uses\nan absolute Euclidean norm, while the sparse solver uses a relative\nEuclidean norm. The default is 1e-3. logical, intent(in), optional :: use_sparse True if the sparse solver should be used vs. the dense solver.  This \nis highly recommended when N is larger than ~1000.  The default is \ntrue such that the sparse solver is used. The sparse solver has\nlinear storage growth and is preferred for large data sets. integer(kind=int32), intent(out), optional :: niter The number of iterations actually performed. Return Value real(kind=real64), allocatable, dimension(:) An N-element array containing the estimate of the derivative.","tags":"","loc":"module\\spectrum_diff.html"},{"title":"spectrum_convolve – SPECTRUM","text":"Uses iso_fortran_env fftpack Variables Type Visibility Attributes Name Initial integer(kind=int32), public, parameter :: SPCTRM_CENTRAL_CONVOLUTION = 50001 A flag for requesting the central portion of the convolution that is \nthe same length as the input signal. integer(kind=int32), public, parameter :: SPCTRM_FULL_CONVOLUTION = 50000 A flag for requesting a full convolution. Functions public pure function convolve (x, y, method) result(rst) Computes the convolution of a signal and kernel. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) The N-element signal. real(kind=real64), intent(in) :: y (:) The M-element kernel. integer(kind=int32), intent(in), optional :: method An optional input that dictates the expected\nconvolution result.  The following options are available. Read more… Return Value real(kind=real64), allocatable, (:) The convolved result.","tags":"","loc":"module\\spectrum_convolve.html"},{"title":"spectrum_integrate.f90 – SPECTRUM","text":"Source Code module spectrum_integrate use iso_fortran_env implicit none private public :: integrate contains ! ------------------------------------------------------------------------------ pure function integrate ( dt , x , iv ) result ( rst ) !! Integrates a data set. real ( real64 ), intent ( in ) :: dt !! The sample interval. real ( real64 ), intent ( in ), dimension (:) :: x !! The data set to integrate. real ( real64 ), intent ( in ), optional :: iv !! The initial value.  The default value is zero. real ( real64 ), allocatable , dimension (:) :: rst !! The integrated data set. ! Local Variables integer ( int32 ) :: i , n , flag real ( real64 ) :: init_val ! Initialization if ( present ( iv )) then init_val = iv else init_val = 0.0d0 end if n = size ( x ) allocate ( rst ( n )) ! Process ! ! Utilize the fixed step-size Adams-Bashforth methods. rst ( 1 ) = init_val if ( n > 2 ) rst ( 2 ) = rst ( 1 ) + dt * x ( 1 ) ! Euler method if ( n > 3 ) rst ( 3 ) = rst ( 2 ) + 0.5d0 * dt * ( 3.0d0 * x ( 2 ) - x ( 1 )) if ( n > 4 ) rst ( 4 ) = rst ( 3 ) + ( dt / 1.2d1 ) * ( 2.3d1 * x ( 3 ) - 1.6d1 * x ( 2 ) + & 5.0d0 * x ( 1 )) if ( n > 5 ) rst ( 5 ) = rst ( 4 ) + ( dt / 2.4d1 ) * ( 5.5d1 * x ( 4 ) - 5.9d1 * x ( 3 ) + & 3.7d1 * x ( 2 ) - 9.0d0 * x ( 1 )) if ( n > 6 ) then do i = 6 , n rst ( i ) = rst ( i - 1 ) + ( dt / 7.2d2 ) * ( 1.901d3 * x ( i - 1 ) - & 2.774d3 * x ( i - 2 ) + 2.616d3 * x ( i - 3 ) - 1.274d3 * x ( i - 4 ) + & 2.51d2 * x ( i - 5 )) end do end if end function ! ------------------------------------------------------------------------------ ! ------------------------------------------------------------------------------ end module","tags":"","loc":"sourcefile\\spectrum_integrate.f90.html"},{"title":"spectrum.f90 – SPECTRUM","text":"Source Code module spectrum use spectrum_windows use spectrum_routines use spectrum_periodogram use spectrum_fft use spectrum_convolve use spectrum_filter use spectrum_filter_design use spectrum_tf use spectrum_diff use spectrum_integrate use spectrum_resample use fftpack , only : zffti , zfftf , zfftb , dffti , dfftf , dfftb , fft , ifft , & fftshift , ifftshift implicit none private ! SPECTRUM_WINDOWS.F90 public :: window public :: window_function public :: rectangular_window public :: hann_window public :: hamming_window public :: welch_window public :: blackman_harris_window public :: flat_top_window ! SPECTRUM_ROUTINES.F90 public :: compute_transform_length public :: frequency_bin_width public :: is_power_of_two public :: next_power_of_two public :: unpack_real_transform public :: cumulative_sum public :: unwrap public :: difference public :: compute_overlap_segment_count public :: overlap public :: remove_mean ! SPECTRUM_PERIODOGRAM.F90 public :: psd public :: csd public :: periodogram public :: cross_periodogram ! SPECTRUM_FFT.F90 public :: rfft public :: irfft public :: stft public :: stft_result ! SPECTRUM_CONVOLVE.F90 public :: convolve public :: SPCTRM_FULL_CONVOLUTION public :: SPCTRM_CENTRAL_CONVOLUTION ! SPECTRUM_FITLER.F90 public :: gaussian_filter public :: tv_filter public :: filter public :: moving_average_filter public :: sinc_filter public :: LOW_PASS_FILTER public :: HIGH_PASS_FILTER public :: BAND_PASS_FILTER public :: BAND_STOP_FILTER ! SPECTRUM_FILTER_DESIGN.F90 public :: design_fir_filter public :: design_iir_filter public :: filter_frequency_response ! SPECTRUM_TF.F90 public :: siso_transfer_function public :: mimo_transfer_function public :: SPCTRM_H1_ESTIMATOR public :: SPCTRM_H2_ESTIMATOR ! SPECTRUM_DIFF.F90 public :: finite_difference public :: tvr_derivative public :: stencil_diff_5 public :: stencil_second_diff_5 public :: filter_diff ! SPECTRUM_INTEGRATE.F90 public :: integrate ! SPECTRUM_RESAMPLE.F90 public :: upsample public :: downsample ! FFTPACK.F90 public :: zffti public :: zfftf public :: zfftb public :: dffti public :: dfftf public :: dfftb public :: fft public :: ifft public :: fftshift public :: ifftshift end module","tags":"","loc":"sourcefile\\spectrum.f90.html"},{"title":"spectrum_fft.f90 – SPECTRUM","text":"Source Code module spectrum_fft use iso_fortran_env use fftpack , only : dffti , dfftf , dfftb use spectrum_windows use spectrum_routines implicit none private public :: stft public :: rfft public :: irfft public :: stft_result type stft_result !! A container for STFT output. complex ( real64 ), allocatable , dimension (:,:) :: stft !! An M-by-N matrix containing the M-element complex-valued !! transforms for each of the N time points studied.  M is the !! size of the positive half of the transform, and N is the total !! number of transformed segments. integer ( int32 ), allocatable , dimension (:) :: offsets !! The starting indices of each window segment. end type contains ! ------------------------------------------------------------------------------ pure function rfft ( x , n ) result ( rst ) !! Computes the Fourier transform of a real-valued data set.  Only the !! positive half of the transform is returned. real ( real64 ), intent ( in ), dimension (:) :: x !! The real-valued array to transform. integer ( int32 ), intent ( in ), optional :: n !! An optional input that can be used to specify the length of the !! transform.  If less than the length of x, x is truncated; however, !! if greater than the length of x, x is padded with zeros. complex ( real64 ), allocatable , dimension (:) :: rst !! The complex-valued result of the transform. ! Local Variables integer ( int32 ) :: i , m , nx , nxfrm , lensav real ( real64 ), allocatable , dimension (:) :: wsave , rrst ! Initialization nx = size ( x ) if ( present ( n )) then nxfrm = n if ( nxfrm <= nx ) then rrst = x ( 1 : nxfrm ) else rrst = [ x , ( 0.0d0 , i = 1 , nxfrm - nx )] end if else nxfrm = nx rrst = x end if lensav = 2 * nxfrm + 15 allocate ( wsave ( lensav )) call dffti ( nxfrm , wsave ) ! Process call dfftf ( nxfrm , rrst , wsave ) m = compute_transform_length ( nxfrm ) allocate ( rst ( m )) rst = unpack_real_transform ( rrst ) end function ! ------------------------------------------------------------------------------ pure function irfft ( x , n ) result ( rst ) !! Computes the inverse Fourier transform for a real-valued data set. complex ( real64 ), intent ( in ), dimension (:) :: x !! The positive half of the transform. integer ( int32 ), intent ( in ), optional :: n !! An optional input that can be used to specify the length of the !! transform.  If less than the length of x, x is truncated; however, !! if greater than the length of x, x is padded with zeros. real ( real64 ), allocatable , dimension (:) :: rst !! The real-valued result of the inverse transform. ! Local Variables integer ( int32 ) :: i , m , nx , nxfrm , lensav , mn real ( real64 ), allocatable , dimension (:) :: wsave ! Initialization nx = size ( x ) if ( mod ( nx , 2 ) == 0 ) then m = 2 * nx - 1 else m = 2 * ( nx - 1 ) end if allocate ( rst ( m ), source = 0.0d0 ) if ( present ( n )) then nxfrm = n else nxfrm = nx end if mn = min (( m + 1 ) / 2 , nx ) rst ( 1 ) = real ( x ( 1 ), real64 ) do i = 2 , mn rst ( 2 * i - 2 ) = real ( x ( i ), real64 ) rst ( 2 * i - 1 ) = aimag ( x ( i )) end do lensav = 2 * nxfrm + 15 allocate ( wsave ( lensav )) ! Process call dfftb ( nxfrm , rst , wsave ) end function ! ------------------------------------------------------------------------------ pure function stft ( win , x ) result ( rst ) !! Computes the short time Fourier transform of a signal. !! !! See Also !! !! - [Wikipedia - Short Time Fourier Transform](https://en.wikipedia.org/wiki/Short-time_Fourier_transform) class ( window ), intent ( in ) :: win !! The window to apply. real ( real64 ), intent ( in ) :: x (:) !! The signal to analyze.  The signal must be longer than the size of !! the window. type ( stft_result ) :: rst !! A container filled with the transform results. ! Local Variables integer ( int32 ) :: i , j , k , m , nx , nxfrm , nk , lwork , i1 , nend real ( real64 ) :: del , sumw , w , fac , scale real ( real64 ), allocatable , dimension (:) :: work , buffer ! Initialization nx = size ( x ) m = win % size ! # of rows in the output matrix (transform length) nxfrm = compute_transform_length ( m ) lwork = 2 * m + 15 nk = compute_overlap_segment_count ( nx , m ) if ( nk > 1 ) then del = ( nx - m ) / ( nk - 1.0d0 ) else del = 0.0d0 end if if ( mod ( m , 2 ) == 0 ) then nend = nxfrm - 1 scale = 2.0d0 / m else nend = nxfrm scale = 2.0d0 / ( m - 1.0d0 ) end if ! Input Checking if ( m > nx ) return ! Memory Allocation allocate ( work ( lwork ), buffer ( m )) allocate ( rst % stft ( nxfrm , nk )) allocate ( rst % offsets ( nk ), source = 0 ) ! Initialize the the transform.  As all transforms are the ! same length, this array can be shared. call dffti ( m , work ) ! Compute each transform do i = 1 , nk ! Compute the offset i1 = int (( i - 1 ) * del + 0.5d0 , int32 ) ! if (present(offsets)) offsets(i) = i1 + 1 rst % offsets ( i ) = i1 + 1 ! Apply the window sumw = 0.0d0 j = 0 do k = 1 , m w = win % evaluate ( j ) j = j + 1 sumw = sumw + w buffer ( k ) = w * x ( k + i1 ) end do fac = m / sumw ! Compute the transform call dfftf ( m , buffer , work ) ! Scale the transform rst % stft ( 1 , i ) = fac * scale * cmplx ( buffer ( 1 ), 0.0d0 , real64 ) do k = 2 , nend rst % stft ( k , i ) = fac * scale * cmplx ( buffer ( 2 * k - 1 ), buffer ( 2 * k ), real64 ) end do if ( nend /= nxfrm ) then rst % stft ( nxfrm , i ) = fac * scale * cmplx ( buffer ( m ), 0.0d0 , real64 ) end if end do end function ! ------------------------------------------------------------------------------ end module","tags":"","loc":"sourcefile\\spectrum_fft.f90.html"},{"title":"spectrum_filter.f90 – SPECTRUM","text":"Source Code module spectrum_filter use iso_fortran_env use spectrum_convolve use spectrum_routines use fftpack implicit none private public :: gaussian_filter public :: tv_filter public :: filter public :: moving_average_filter public :: sinc_filter public :: LOW_PASS_FILTER public :: HIGH_PASS_FILTER public :: BAND_PASS_FILTER public :: BAND_STOP_FILTER integer ( int32 ), parameter :: LOW_PASS_FILTER = 1 !! Denotes a low-pass filter. integer ( int32 ), parameter :: HIGH_PASS_FILTER = 2 !! Denotes a high-pass filter. integer ( int32 ), parameter :: BAND_PASS_FILTER = 3 !! Denotes a band-pass filter. integer ( int32 ), parameter :: BAND_STOP_FILTER = 4 !! Denotes a band-stop filter. contains ! ****************************************************************************** ! GAUSSIAN FILTER ! ------------------------------------------------------------------------------ pure function gaussian_filter ( x , alpha , k ) result ( rst ) !! Applies a Gaussian filter to a signal. real ( real64 ), intent ( in ) :: x (:) !! An N-element array containing the signal to filter. real ( real64 ), intent ( in ) :: alpha !! A parameter that specifies the number of standard deviations !!  \\sigma  desired in the kernel.  This parameter is related to the !! standard deviation by  \\sigma = \\frac{k - 1}{2 \\alpha} . integer ( int32 ), intent ( in ) :: k !! The kernel size.  This value must be a positive, non-zero !! integer value less than N. real ( real64 ), allocatable :: rst (:) !! An N-element array containing the filtered signal. ! Local Variables integer ( int32 ) :: i , kappa , nk real ( real64 ) :: sumg real ( real64 ), allocatable :: g (:) ! Initialization if ( mod ( k , 2 ) == 0 ) then nk = k + 1 else nk = k end if kappa = - ( nk - 1 ) / 2 sumg = 0.0d0 ! Input Checking if ( nk > size ( x ) . or . k < 1 ) return if ( alpha <= 0.0d0 ) return ! Memory Allocation allocate ( g ( nk )) ! Define the kernel do i = 1 , nk g ( i ) = exp ( - 0.5d0 * ( 2.0d0 * alpha * kappa / ( nk - 1.0d0 )) ** 2 ) kappa = kappa + 1 sumg = sumg + g ( i ) end do ! Normalize the kernel to have a sum of one g = g / sumg ! Compute the convolution and keep only the non-poluted data rst = convolve ( x , g , SPCTRM_CENTRAL_CONVOLUTION ) end function ! ****************************************************************************** ! TOTAL VARIATION FILTERING ! ------------------------------------------------------------------------------ ! REF: ! https://eeweb.engineering.nyu.edu/iselesni/lecture_notes/TV_filtering.pdf pure function tv_filter ( x , lambda , niter ) result ( rst ) !! Applies a total-variation filter to a signal. !! !! The algorithm used by this routine is based upon the algorithm presented !! by [Selesnick and Bayram] !! (https://eeweb.engineering.nyu.edu/iselesni/lecture_notes/TV_filtering.pdf). real ( real64 ), intent ( in ) :: x (:) !! An N-element array containing the signal to filter. real ( real64 ), intent ( in ) :: lambda !! The regularization parameter.  The actual value to use !! is problem dependent, but the noisier the data, the larger this value !! should be.  A good starting point is typically 0.3 - 0.5; however, the !! actual value is problem dependent. integer ( int32 ), intent ( in ), optional :: niter !! An optional parameter controlling the number of iterations performed. !! The default limit is 10 iterations. real ( real64 ), allocatable :: rst (:) !! An N-element array containing the filtered signal. ! Parameters real ( real64 ), parameter :: alpha = 4.0d0 ! Local Variables integer ( int32 ) :: i , k , nit , n real ( real64 ) :: t real ( real64 ), allocatable :: z (:), work (:), dx (:) ! Initialization if ( present ( niter )) then nit = niter else nit = 10 end if n = size ( x ) ! Input Checking if ( nit < 1 ) return ! Memory Allocations allocate ( rst ( n )) allocate ( z ( n - 1 ), source = 0.0d0 ) allocate ( dx ( n - 1 )) allocate ( work ( n )) ! Process t = 0.5d0 * lambda do i = 1 , nit work ( 2 : n - 1 ) = difference ( z ) work ( 1 ) = z ( 1 ) work ( n ) = - z ( n - 1 ) rst = x + work dx = difference ( rst ) do k = 1 , n - 1 z ( k ) = z ( k ) + dx ( k ) / alpha z ( k ) = max ( min ( z ( k ), t ), - t ) end do end do end function ! ------------------------------------------------------------------------------ pure function filter ( b , a , x , delays ) result ( rst ) !! Applies the specified filter to a signal. !! !! The description of the filter in the Z-transform domain is a rational !! transfer function of the form: !! !!  Y(z) = \\frac{b(1) + b(2) z&#94;{-1} + ... + b(n_b + 1)z&#94;{-n_b}} !! {1 + a(2) z&#94;{-1} + ... + a(n_a + 1) z&#94;{-n_a}} X(z) , !! which handles both IIR and FIR filters. The above form assumes a !! normalization of a(1) = 1; however, the routine will appropriately !! handle the situation where a(1) is not set to one. real ( real64 ), intent ( in ) :: b (:) !! The numerator coefficients of the rational transfer function. real ( real64 ), intent ( in ) :: a (:) !! The denominator coefficients of the ration transfer function.  In !! the case of an FIR filter, this parameter should be set to a !! one-element array with a value of one.  Regardless, the value of !! a(1) must be non-zero. real ( real64 ), intent ( in ) :: x (:) !! An N-element array containing the signal to filter. real ( real64 ), intent ( in ), optional , target :: delays (:) !! An optional array of length MAX(size(a), size(b)) - 1 that provides !! the initial conditions for filter delays, and on ouput, the final !! conditions for filter delays. real ( real64 ), allocatable :: rst (:) !! An N-element array containing the filtered signal. ! Parameters real ( real64 ), parameter :: tol = 2.0d0 * epsilon ( 2.0d0 ) ! Local Variables integer ( int32 ) :: i , m , na , nb , n , nx real ( real64 ), allocatable , dimension (:) :: aa , bb , z ! Initialization nx = size ( x ) na = size ( a ) nb = size ( b ) if ( na > nb ) then n = na else n = nb end if ! Input Checking if ( na < 1 ) return if ( abs ( a ( 1 )) < tol ) return ! Memory Allocations if ( present ( delays )) then ! if (size(delays) /= n - 1) return ! zptr(1:n-1) => delays allocate ( z ( n - 1 ), source = delays ) else ! allocate(zdef(n - 1), source = 0.0d0) ! zptr(1:n-1) => zdef allocate ( z ( n - 1 ), source = 0.0d0 ) end if allocate ( aa ( n ), bb ( n ), rst ( nx ), source = 0.0d0 ) ! Copy over A & B and scale such that A(1) = 1 if ( abs ( a ( 1 ) - 1.0d0 ) > tol ) then bb ( 1 : nb ) = b / a ( 1 ) aa ( 1 : na ) = a / a ( 1 ) else bb ( 1 : nb ) = b aa ( 1 : na ) = a end if ! Process if ( na > 1 ) then ! IIR do m = 1 , nx rst ( m ) = bb ( 1 ) * x ( m ) + z ( 1 ) do i = 2 , n - 1 z ( i - 1 ) = bb ( i ) * x ( m ) + z ( i ) - aa ( i ) * rst ( m ) end do z ( n - 1 ) = bb ( n ) * x ( m ) - aa ( n ) * rst ( m ) ! Omit z(n), which is always zero end do else ! FIR do m = 1 , nx rst ( m ) = bb ( 1 ) * x ( m ) + z ( 1 ) do i = 2 , n - 1 z ( i - 1 ) = bb ( i ) * x ( m ) + z ( i ) end do ! Omit z(n), which is always zero end do end if end function ! ------------------------------------------------------------------------------ pure function moving_average_filter ( navg , x ) result ( rst ) !! Applies a moving average filter to a signal. integer ( int32 ), intent ( in ) :: navg !! The size of the averaging window.  This parameter must be positive !! and non-zero. real ( real64 ), intent ( in ) :: x (:) !! An N-element array containing the signal to filter. real ( real64 ), allocatable :: rst (:) !! An N-element array containing the filtered signal. ! Local Variables real ( real64 ) :: a ( 1 ), b ( navg ) ! Input Check if ( navg < 1 ) return ! Process a = 1.0d0 b = 1.0d0 / navg rst = filter ( b , a , x ) end function ! ****************************************************************************** ! V1.1.3 ADDITIONS ! ------------------------------------------------------------------------------ pure function sinc_filter ( fc , fs , x , fc2 , ftype ) result ( rst ) !! Applies a sinc-in-time filter (rectangular frequency response). real ( real64 ), intent ( in ) :: fc !! The filter cutoff frequency, in Hz. real ( real64 ), intent ( in ) :: fs !! The sampling frequency, in Hz. real ( real64 ), intent ( in ), dimension (:) :: x !! The signal to filter. real ( real64 ), intent ( in ), optional :: fc2 !! The second cutoff frequency for band-pass and band-stop filters. integer ( int32 ), intent ( in ), optional :: ftype !! The filter type.  This parameter must be one of the following values: !! !!  - LOW_PASS_FILTER: Denotes a low-pass filter. !! !!  - HIGH_PASS_FILTER: Denotes a high-pass filter. !! !!  - BAND_PASS_FILTER: Denotes a band-pass filter. !! !!  - BAND_STOP_FILTER: Denotes a band-stop filter. !! !! The default value is LOW_PASS_FILTER. real ( real64 ), allocatable , dimension (:) :: rst !! The filtered signal. ! Local Variables integer ( int32 ) :: start , finish , n , nw , filterType real ( real64 ) :: df real ( real64 ), allocatable , dimension (:) :: wsave ! Initialization if ( present ( ftype )) then filterType = ftype else filterType = LOW_PASS_FILTER end if n = size ( x ) nw = 2 * n + 15 ! Input Checking if ( fs <= 0.0d0 ) then return end if if ( fc <= 0.0d0 ) then return end if if ( fc >= 0.5d0 * fs ) then return end if if ( filterType < LOW_PASS_FILTER . or . filterType > BAND_STOP_FILTER ) then return end if if ( filterType == BAND_PASS_FILTER . or . filterType == BAND_STOP_FILTER ) then if (. not . present ( fc2 )) then return end if if ( fc2 <= 0.0d0 ) then return end if if ( fc2 >= 0.5d0 * fs ) then return end if end if ! Memory Allocations allocate ( rst ( n ), source = x ) allocate ( wsave ( nw )) ! Initialize and compute the Fourier transform call dffti ( n , wsave ) call dfftf ( n , rst , wsave ) ! Zero out anything above the cutoff frequency df = frequency_bin_width ( fs , n ) start = floor ( fc / df ) * 2 if ( present ( fc2 )) then finish = floor ( fc2 / df ) * 2 end if ! Apply the appropriate filter select case ( filterType ) case ( LOW_PASS_FILTER ) ! Zero out anything above the cutoff frequency rst ( start : n ) = 0.0d0 case ( HIGH_PASS_FILTER ) ! Zero out anything below the cutoff frequency rst ( 1 : start ) = 0.0d0 case ( BAND_PASS_FILTER ) ! Zero out anything below the first cutoff frequency rst ( 1 : start ) = 0.0d0 ! Zero out anything above the second cutoff frequency rst ( finish : n ) = 0.0d0 case ( BAND_STOP_FILTER ) ! Zero out anything between the two cutoff frequencies rst ( start : finish ) = 0.0d0 end select ! Compute the inverse transform to retrieve the filtered signal call dfftb ( n , rst , wsave ) rst = rst / n end function ! ------------------------------------------------------------------------------ end module","tags":"","loc":"sourcefile\\spectrum_filter.f90.html"},{"title":"spectrum_resample.f90 – SPECTRUM","text":"Source Code module spectrum_resample use iso_fortran_env use spectrum_filter implicit none private public :: upsample public :: downsample contains ! ------------------------------------------------------------------------------ pure function upsample ( n , fs , x ) result ( rst ) !! Upsamples an evenly sampled signal by the specified factor. integer ( int32 ), intent ( in ) :: n !! The upsample factor.  This value must be non-zero and positive !! valued. real ( real64 ), intent ( in ) :: fs !! The original signal sample rate, in Hz. real ( real64 ), intent ( in ), dimension (:) :: x !! The signal to upsample. real ( real64 ), allocatable , dimension (:) :: rst !! The upsampled signal. ! Local Variables integer ( int32 ) :: i , npts , nnew ! Initialization npts = size ( x ) nnew = n * npts ! Input Checking if ( n < 1 ) return ! Memory Allocations allocate ( rst ( nnew ), source = 0.0d0 ) ! Quick Return if ( n == 1 ) then rst = x return end if ! Populate the \"upsampled\" signal do i = 1 , npts rst ( n * ( i - 1 ) + 1 ) = x ( i ) end do ! Filter the upsampled frequency at the sample rate of the old signal rst = sinc_filter ( 0.5d0 * fs , fs * n , rst ) * n end function ! ------------------------------------------------------------------------------ pure function downsample ( n , fs , x ) result ( rst ) !! Downsamples an evenly sampled signal by the specified factor. integer ( int32 ), intent ( in ) :: n !! The downsample factor.  The value must be non-zer and positive !! valued. real ( real64 ), intent ( in ) :: fs !! The original signal sample rate, in Hz. real ( real64 ), intent ( in ), dimension (:) :: x !! The signal to downsample. real ( real64 ), allocatable , dimension (:) :: rst !! The downsampled signal. ! Local Variables integer ( int32 ) :: i , npts , nnew real ( real64 ), allocatable , dimension (:) :: xf ! Initialization npts = size ( x ) nnew = npts / n ! Input Checking if ( n < 1 ) return ! Memory Allocations allocate ( rst ( nnew ), source = 0.0d0 ) ! Quick Return if ( n == 1 ) then rst = x return end if ! Filter the signal at the downsampled frequency - prevents aliasing issues xf = sinc_filter ( 0.5d0 * fs / n , fs , x ) ! Resample do i = 1 , nnew rst ( i ) = xf ( n * ( i - 1 ) + 1 ) end do end function ! ------------------------------------------------------------------------------ end module","tags":"","loc":"sourcefile\\spectrum_resample.f90.html"},{"title":"spectrum_filter_design.f90 – SPECTRUM","text":"Source Code module spectrum_filter_design use iso_fortran_env use spectrum_filter , only : LOW_PASS_FILTER , HIGH_PASS_FILTER , & BAND_PASS_FILTER , BAND_STOP_FILTER implicit none private public :: design_fir_filter public :: design_iir_filter public :: filter_frequency_response contains ! ------------------------------------------------------------------------------ pure subroutine design_fir_filter ( n , fc , fs , b , a , fc2 , ftype ) !! Designs a Hamming-windowed, linear-phase FIR filter. !! !! The returned coefficients use the same convention as filter: b contains !! the numerator coefficients in increasing delay order and a is [1.0]. integer ( int32 ), intent ( in ) :: n !! The requested number of taps. Even values are increased by one. real ( real64 ), intent ( in ) :: fc !! The first cutoff frequency, in Hz. real ( real64 ), intent ( in ) :: fs !! The sampling frequency, in Hz. real ( real64 ), allocatable , intent ( out ) :: b (:) !! The numerator coefficients of the designed filter. real ( real64 ), allocatable , intent ( out ) :: a (:) !! The denominator coefficients. This is always [1.0]. real ( real64 ), intent ( in ), optional :: fc2 !! The second cutoff frequency for band-pass and band-stop filters. integer ( int32 ), intent ( in ), optional :: ftype !! The filter type. The default is LOW_PASS_FILTER. integer ( int32 ) :: i , ntaps , filter_type , midpoint real ( real64 ) :: cutoff2 , offset , sum_b ntaps = n if ( mod ( ntaps , 2 ) == 0 ) ntaps = ntaps + 1 filter_type = LOW_PASS_FILTER if ( present ( ftype )) filter_type = ftype cutoff2 = 0.0d0 if ( present ( fc2 )) cutoff2 = fc2 if ( ntaps < 1 . or . fs <= 0.0d0 . or . fc <= 0.0d0 . or . & fc >= 0.5d0 * fs ) return if ( filter_type < LOW_PASS_FILTER . or . filter_type > BAND_STOP_FILTER ) return if ( filter_type == BAND_PASS_FILTER . or . filter_type == BAND_STOP_FILTER ) then if (. not . present ( fc2 ) . or . cutoff2 <= fc . or . cutoff2 >= 0.5d0 * fs ) return end if allocate ( b ( ntaps ), a ( 1 )) a = 1.0d0 midpoint = ( ntaps - 1 ) / 2 do i = 1 , ntaps offset = real ( i - 1 - midpoint , real64 ) b ( i ) = windowed_kernel ( fc , fs , offset , ntaps ) end do select case ( filter_type ) case ( HIGH_PASS_FILTER ) b = - b b ( midpoint + 1 ) = b ( midpoint + 1 ) + 1.0d0 case ( BAND_PASS_FILTER , BAND_STOP_FILTER ) do i = 1 , ntaps offset = real ( i - 1 - midpoint , real64 ) b ( i ) = b ( i ) - windowed_kernel ( cutoff2 , fs , offset , ntaps ) end do if ( filter_type == BAND_STOP_FILTER ) then b ( midpoint + 1 ) = b ( midpoint + 1 ) + 1.0d0 else b = - b end if end select sum_b = sum ( b ) if ( filter_type == LOW_PASS_FILTER . or . filter_type == BAND_STOP_FILTER ) then if ( abs ( sum_b ) > epsilon ( 1.0d0 )) b = b / sum_b end if end subroutine ! ------------------------------------------------------------------------------ pure subroutine design_iir_filter ( n , fc , fs , b , a , ftype ) !! Designs an nth-order Butterworth IIR low-pass or high-pass filter. !! !! The returned coefficients are normalized such that a(1) is one and use !! the increasing-delay convention required by filter. integer ( int32 ), intent ( in ) :: n !! The Butterworth filter order. real ( real64 ), intent ( in ) :: fc !! The cutoff frequency, in Hz. real ( real64 ), intent ( in ) :: fs !! The sampling frequency, in Hz. real ( real64 ), allocatable , intent ( out ) :: b (:) !! The numerator coefficients of the designed filter. real ( real64 ), allocatable , intent ( out ) :: a (:) !! The denominator coefficients of the designed filter. integer ( int32 ), intent ( in ), optional :: ftype !! LOW_PASS_FILTER (default) or HIGH_PASS_FILTER. integer ( int32 ) :: i , j , filter_type real ( real64 ) :: analog_cutoff , gain , pi , phase , numerator , denominator_sum complex ( real64 ) :: pole , root complex ( real64 ), allocatable :: denominator (:) filter_type = LOW_PASS_FILTER if ( present ( ftype )) filter_type = ftype if ( n < 1 . or . fs <= 0.0d0 . or . fc <= 0.0d0 . or . & fc >= 0.5d0 * fs ) return if ( filter_type /= LOW_PASS_FILTER . and . & filter_type /= HIGH_PASS_FILTER ) return pi = acos ( - 1.0d0 ) analog_cutoff = 2.0d0 * fs * tan ( pi * fc / fs ) allocate ( b ( n + 1 ), a ( n + 1 ), denominator ( n + 1 )) b = 0.0d0 denominator = ( 0.0d0 , 0.0d0 ) b ( 1 ) = 1.0d0 denominator ( 1 ) = ( 1.0d0 , 0.0d0 ) do i = 1 , n phase = pi * real ( 2 * i + n - 1 , real64 ) / real ( 2 * n , real64 ) pole = analog_cutoff * exp ( cmplx ( 0.0d0 , phase , real64 )) root = ( 2.0d0 * fs + pole ) / ( 2.0d0 * fs - pole ) do j = i + 1 , 2 , - 1 denominator ( j ) = denominator ( j ) - root * denominator ( j - 1 ) if ( filter_type == LOW_PASS_FILTER ) then b ( j ) = b ( j ) + b ( j - 1 ) else b ( j ) = b ( j ) - b ( j - 1 ) end if end do end do a = real ( denominator , real64 ) if ( filter_type == LOW_PASS_FILTER ) then gain = sum ( a ) / sum ( b ) else numerator = 0.0d0 denominator_sum = 0.0d0 do i = 1 , n + 1 numerator = numerator + ( - 1.0d0 ) ** ( i - 1 ) * a ( i ) denominator_sum = denominator_sum + ( - 1.0d0 ) ** ( i - 1 ) * b ( i ) end do gain = numerator / denominator_sum end if b = gain * b end subroutine ! ------------------------------------------------------------------------------ pure function filter_frequency_response ( b , a , f , fs ) result ( rst ) !! Computes the complex frequency response of a rational filter. !! !! The coefficient ordering is the same as [[filter]]: b(i) and a(i) !! where z = \\exp{\\frac{2 \\pi i f}{f_s}}. The returned values are !! therefore H(f) = \\frac{B(z)}{A(z)} at each requested frequency. real ( real64 ), intent ( in ) :: b (:) !! The numerator coefficients of the rational transfer function. real ( real64 ), intent ( in ) :: a (:) !! The denominator coefficients of the rational transfer function. real ( real64 ), intent ( in ) :: f (:) !! The frequencies at which to evaluate the response, in Hz. real ( real64 ), intent ( in ) :: fs !! The sampling frequency, in Hz. complex ( real64 ), allocatable :: rst (:) !! The complex frequency response at each frequency in f. integer ( int32 ) :: i , j , n real ( real64 ) :: pi , phase complex ( real64 ) :: z , numerator , denominator n = size ( f ) if ( size ( a ) < 1 . or . fs <= 0.0d0 ) return allocate ( rst ( n ), source = ( 0.0d0 , 0.0d0 )) pi = acos ( - 1.0d0 ) do i = 1 , n phase = 2.0d0 * pi * f ( i ) / fs z = exp ( cmplx ( 0.0d0 , - phase , real64 )) numerator = ( 0.0d0 , 0.0d0 ) denominator = ( 0.0d0 , 0.0d0 ) do j = size ( b ), 1 , - 1 numerator = numerator * z + b ( j ) end do do j = size ( a ), 1 , - 1 denominator = denominator * z + a ( j ) end do if ( abs ( denominator ) > tiny ( 1.0d0 )) then rst ( i ) = numerator / denominator end if end do end function ! ------------------------------------------------------------------------------ pure function lowpass_kernel ( fc , fs , offset ) result ( value ) real ( real64 ), intent ( in ) :: fc , fs , offset real ( real64 ) :: value , pi , argument pi = acos ( - 1.0d0 ) argument = 2.0d0 * fc / fs * offset if ( abs ( argument ) < epsilon ( 1.0d0 )) then value = 2.0d0 * fc / fs else value = 2.0d0 * fc / fs * sin ( pi * argument ) / ( pi * argument ) end if end function ! ------------------------------------------------------------------------------ pure function windowed_kernel ( fc , fs , offset , ntaps ) result ( value ) real ( real64 ), intent ( in ) :: fc , fs , offset integer ( int32 ), intent ( in ) :: ntaps real ( real64 ) :: value , pi , index , window pi = acos ( - 1.0d0 ) value = lowpass_kernel ( fc , fs , offset ) if ( ntaps > 1 ) then index = offset + 0.5d0 * real ( ntaps - 1 , real64 ) window = 0.54d0 - 0.46d0 * cos ( 2.0d0 * pi * index / real ( ntaps - 1 , real64 )) value = window * value end if end function ! ------------------------------------------------------------------------------ end module","tags":"","loc":"sourcefile\\spectrum_filter_design.f90.html"},{"title":"spectrum_periodogram.f90 – SPECTRUM","text":"Source Code module spectrum_periodogram use iso_fortran_env use spectrum_windows use spectrum_routines use fftpack implicit none private public :: psd public :: csd public :: periodogram public :: cross_periodogram contains ! ------------------------------------------------------------------------------ pure function psd ( win , x , fs , nfft ) result ( rst ) !! Computes the power spectral density (PSD) of a signal via Welch's !! method. !! !! References !! !! - Welch, P.D. \"The Use of Fast Fourier Transform for the Estimation of !!  Power Spectra: A Method Based on Time Averaging Over Short, Modified !!  Periodograms.\" IEEE Transactions on Audio and Electroacoustics, !!  AU-15 (2): 70-73, 1967. !! !! - [Wikipedia - Welch's Method](https://en.wikipedia.org/wiki/Welch%27s_method) class ( window ), intent ( in ) :: win !! The window to apply.  The size of the window must be non-zero and !! positive-valued. real ( real64 ), intent ( in ) :: x (:) !! The signal to transform. real ( real64 ), intent ( in ), optional :: fs !! An optional input, that if supplied, allows for normalization of !! the computed spectrum by the frequency resolution. integer ( int32 ), intent ( in ), optional :: nfft !! An optional input that can be used to force the length of each !! individual DFT operation by padding any remaining space with zeros. !! If not supplied, the window size is used to determine the size of !! the DFT. real ( real64 ), allocatable :: rst (:) !! An array containing the discrete PSD estimate.  The estimate is !! returned at discrete frequency intervals that can be determined by !! a call to frequency_bin_width. ! Local Variables logical :: init integer ( int32 ) :: i , nx , nxfrm , nw , nk , nf , lwork real ( real64 ) :: fres , fac real ( real64 ), allocatable , dimension (:) :: work , xw , buffer complex ( real64 ), allocatable :: cwork (:) ! Initialization nx = size ( x ) nw = win % size if ( present ( nfft )) then nf = nfft else nf = nw end if nxfrm = compute_transform_length ( nf ) nk = compute_overlap_segment_count ( nx , nw ) lwork = 3 * nf + 15 ! Input Checking if ( size ( x ) < 2 ) return ! Memory Allocation allocate ( rst ( nxfrm ), source = 0.0d0 ) allocate ( work ( lwork )) allocate ( xw ( nw )) allocate ( buffer ( nxfrm )) allocate ( cwork ( nxfrm )) ! Cycle over each segment init = . true . do i = 1 , nk call overlap ( x , i , nw , xw ) call periodogram_driver ( win , xw , buffer , fs , nf , work , init , cwork ) rst = rst + buffer init = . false . end do ! Average the result rst = rst / real ( nk , real64 ) end function ! ------------------------------------------------------------------------------ pure function csd ( win , x , y , fs , nfft ) result ( rst ) !! Computes the cross spectral density (CSD) of a signal via Welch's !! method (sometimes referred to as cross power spectral density !! or CPSD). !! !! References !! !! - Welch, P.D. \"The Use of Fast Fourier Transform for the Estimation of !!  Power Spectra: A Method Based on Time Averaging Over Short, Modified !!  Periodograms.\" IEEE Transactions on Audio and Electroacoustics, !!  AU-15 (2): 70-73, 1967. !! !! - [Wikipedia - Welch's Method](https://en.wikipedia.org/wiki/Welch%27s_method) !! !! - [Wikipedia - Cross Power Spectral Density](https://en.wikipedia.org/wiki/Spectral_density#Cross-spectral_density) class ( window ), intent ( in ) :: win !! The window to apply.  The size of the window must be non-zero and !! positive-valued. real ( real64 ), intent ( in ) :: x (:) !! The first N-element signal to transform. real ( real64 ), intent ( in ) :: y (:) !! The second N-element signal to transform. real ( real64 ), intent ( in ), optional :: fs !! An optional input, that if supplied, allows for normalization of !! the computed spectrum by the frequency resolution. integer ( int32 ), intent ( in ), optional :: nfft !! An optional input that can be used to force the length of each !! individual DFT operation by padding any remaining space with zeros. !! If not supplied, the window size is used to determine the size of !! the DFT. complex ( real64 ), allocatable :: rst (:) !! An array containing the discrete CSD estimate.  The estimate is !! returned at discrete frequency intervals that can be determined by !! a call to frequency_bin_width. ! Local Variables logical :: init integer ( int32 ) :: i , nx , ny , nw , nk , nf , lwork , nxfrm real ( real64 ) :: fres , fac real ( real64 ), allocatable , dimension (:) :: work , xw , yw complex ( real64 ), allocatable , dimension (:) :: cwork , buffer ! Initialization nx = size ( x ) ny = size ( y ) nw = win % size if ( present ( nfft )) then nf = nfft else nf = nw end if nxfrm = compute_transform_length ( nf ) nk = compute_overlap_segment_count ( nx , nw ) lwork = 4 * nf + 15 ! Input Checking if ( nx < 2 . or . ny < 2 ) return ! Memory Allocation allocate ( rst ( nxfrm ), source = ( 0.0d0 , 0.0d0 )) allocate ( work ( lwork )) allocate ( xw ( nw )) allocate ( yw ( nw )) allocate ( buffer ( nxfrm )) allocate ( cwork ( 2 * nxfrm )) ! Cycle over each segment init = . true . do i = 1 , nk call overlap ( x , i , nw , xw ) call overlap ( y , i , nw , yw ) call cross_periodogram_driver ( win , xw , yw , buffer , fs , nf , work , & init , cwork ) rst = rst + buffer init = . false . end do ! Average the result rst = rst / real ( nk , real64 ) end function ! ------------------------------------------------------------------------------ pure function periodogram ( win , x , fs , nfft ) result ( rst ) !! Computes the periodogram of a signal. class ( window ), intent ( in ) :: win !! The window to apply.  The size of the window must be non-zero and !! positive-valued. real ( real64 ), intent ( in ) :: x (:) !! The signal to transform. real ( real64 ), intent ( in ), optional :: fs !! An optional input, that if supplied, allows for normalization of !! the computed spectrum by the frequency resolution. integer ( int32 ), intent ( in ), optional :: nfft !! An optional input that can be used to force the length of each !! individual DFT operation by padding any remaining space with zeros. !! If not supplied, the window size is used to determine the size of !! the DFT. real ( real64 ), allocatable :: rst (:) !! An array containing the discrete PSD estimate.  The estimate is !! returned at discrete frequency intervals that can be determined by !! a call to frequency_bin_width. ! Local Variables integer ( int32 ) :: n , nxfrm , nf ! Initialization n = size ( x ) if ( present ( nfft )) then nf = nfft else nf = n end if nxfrm = compute_transform_length ( nf ) ! Memory Allocation allocate ( rst ( nxfrm )) ! Process call periodogram_driver ( win , x , rst , fs = fs , nfft = nfft ) end function ! ------------------------------------------------------------------------------ pure function cross_periodogram ( win , x , y , fs , nfft ) result ( rst ) !! Computes the cross-spectral periodogram of two signals. class ( window ), intent ( in ) :: win !! The window to apply.  The size of the window must be non-zero and !! positive-valued. real ( real64 ), intent ( in ) :: x (:) !! The first N-element signal to transform. real ( real64 ), intent ( in ) :: y (:) !! The second N-element signal to transform. real ( real64 ), intent ( in ), optional :: fs !! An optional input, that if supplied, allows for normalization of !! the computed spectrum by the frequency resolution. integer ( int32 ), intent ( in ), optional :: nfft !! An optional input that can be used to force the length of each !! individual DFT operation by padding any remaining space with zeros. !! If not supplied, the window size is used to determine the size of !! the DFT. complex ( real64 ), allocatable :: rst (:) !! An array containing the discrete cross periodogram estimate.  The !! estimate is returned at discrete frequency intervals that can be !! determined by a call to frequency_bin_width. ! Local Variables integer ( int32 ) :: nx , nxfrm , nf ! Initialization nx = size ( x ) if ( present ( nfft )) then nf = nfft else nf = nx end if nxfrm = compute_transform_length ( nf ) ! Memory Allocation allocate ( rst ( nxfrm )) ! Process call cross_periodogram_driver ( win , x , y , rst , fs = fs , nfft = nfft ) end function ! ------------------------------------------------------------------------------ pure subroutine periodogram_driver ( win , x , xfrm , fs , nfft , work , initxfrm , & cwork ) ! Arguments class ( window ), intent ( in ) :: win ! size = n real ( real64 ), intent ( in ) :: x (:) ! size = n real ( real64 ), intent ( out ) :: xfrm (:) ! size = m = (nfft + 1) / 2 or nfft / 2 + 1 real ( real64 ), intent ( in ), optional :: fs integer ( int32 ), intent ( in ), optional :: nfft ! defaults to n, must be at least n real ( real64 ), intent ( out ), optional , target :: work (:) ! size = 3 * nfft + 15 logical , intent ( in ), optional :: initxfrm complex ( real64 ), intent ( out ), optional , target :: cwork (:) ! size = m ! Local Variables logical :: init integer ( int32 ) :: i , j , nx , nxfrm , nf , lw , lwork real ( real64 ) :: wval , wsum , scale , fac , df real ( real64 ), allocatable , target , dimension (:) :: wdef real ( real64 ), pointer , dimension (:) :: w , xw complex ( real64 ), allocatable , target , dimension (:) :: cwdef complex ( real64 ), pointer , dimension (:) :: cw ! Initialization nx = size ( x ) if ( present ( nfft )) then nf = nfft else nf = nx end if nxfrm = compute_transform_length ( nf ) lw = 2 * nf + 15 lwork = lw + nf if ( present ( work ) . and . present ( initxfrm )) then init = initxfrm else init = . true . end if if ( mod ( nx , 2 ) == 0 ) then scale = 2.0d0 / nx else scale = 2.0d0 / ( nx - 1.0d0 ) end if ! Input Checking if ( win % size /= nx ) return if ( size ( xfrm ) /= nxfrm ) return if ( nf < nx ) return ! Workspace if ( present ( work )) then if ( size ( work ) < lwork ) return w ( 1 : lw ) => work ( 1 : lw ) xw ( 1 : nf ) => work ( lw + 1 : lwork ) else allocate ( wdef ( lwork )) w ( 1 : lw ) => wdef ( 1 : lw ) xw ( 1 : nf ) => wdef ( lw + 1 : lwork ) end if if ( init ) call dffti ( nf , w ) if ( present ( cwork )) then if ( size ( cwork ) < nxfrm ) return cw ( 1 : nxfrm ) => cwork ( 1 : nxfrm ) else allocate ( cwdef ( nxfrm )) cw ( 1 : nxfrm ) => cwdef ( 1 : nxfrm ) end if ! Apply the window wsum = 0.0d0 do i = 1 , nx j = i - 1 wval = win % evaluate ( j ) wsum = wsum + wval xw ( i ) = wval * x ( i ) end do fac = nx / wsum ! Pad with zeros if ( nf > nx ) xw ( nx + 1 : nf ) = 0.0d0 ! Compute the transform call dfftf ( nf , xw , w ) cw = unpack_real_transform ( xw , fac * scale ) ! Compute the power from the windowed transform xfrm = real ( cw * conjg ( cw )) ! Normalize by frequency if ( present ( fs )) then df = frequency_bin_width ( fs , nf ) xfrm = xfrm / df end if end subroutine ! ------------------------------------------------------------------------------ pure subroutine cross_periodogram_driver ( win , x , y , xfrm , fs , nfft , work , & initxfrm , cwork ) ! Arguments class ( window ), intent ( in ) :: win ! size = n real ( real64 ), intent ( in ) :: x (:), y (:) ! size = n complex ( real64 ), intent ( out ) :: xfrm (:) ! size = m = (nfft + 1) / 2 or nfft / 2 + 1 real ( real64 ), intent ( in ), optional :: fs integer ( int32 ), intent ( in ), optional :: nfft ! defaults to n, must be at least n real ( real64 ), intent ( out ), optional , target :: work (:) ! size = 4 * nfft + 15 logical , intent ( in ), optional :: initxfrm complex ( real64 ), intent ( out ), optional , target :: cwork (:) ! size = 2 * m ! Local Variables logical :: init integer ( int32 ) :: i , j , nx , ny , nxfrm , nf , lw , lwork real ( real64 ) :: wval , wsum , scale , fac , df real ( real64 ), allocatable , target , dimension (:) :: wdef real ( real64 ), pointer , dimension (:) :: w , xw , yw complex ( real64 ), allocatable , target , dimension (:) :: cwdef complex ( real64 ), pointer , dimension (:) :: cx , cy ! Initialization nx = size ( x ) ny = size ( y ) if ( present ( nfft )) then nf = nfft else nf = nx end if nxfrm = compute_transform_length ( nf ) lw = 2 * nf + 15 lwork = lw + 2 * nf if ( present ( work ) . and . present ( initxfrm )) then init = initxfrm else init = . true . end if if ( mod ( nx , 2 ) == 0 ) then scale = 2.0d0 / nx else scale = 2.0d0 / ( nx - 1.0d0 ) end if ! Input Checking if ( nx /= ny ) return if ( win % size /= nx ) return if ( size ( xfrm ) /= nxfrm ) return if ( nf < nx ) return ! Workspace if ( present ( work )) then if ( size ( work ) < lwork ) return w ( 1 : lw ) => work ( 1 : lw ) xw ( 1 : nf ) => work ( lw + 1 : lw + nf ) yw ( 1 : nf ) => work ( lw + nf + 1 : lwork ) else allocate ( wdef ( lwork )) w ( 1 : lw ) => wdef ( 1 : lw ) xw ( 1 : nf ) => wdef ( lw + 1 : lw + nf ) yw ( 1 : nf ) => wdef ( lw + nf + 1 : lwork ) end if if ( init ) call dffti ( nf , w ) if ( present ( cwork )) then if ( size ( cwork ) /= 2 * nxfrm ) return cx ( 1 : nxfrm ) => cwork ( 1 : nxfrm ) cy ( 1 : nxfrm ) => cwork ( nxfrm + 1 : 2 * nxfrm ) else allocate ( cwdef ( 2 * nxfrm )) cx ( 1 : nxfrm ) => cwdef ( 1 : nxfrm ) cy ( 1 : nxfrm ) => cwdef ( nxfrm + 1 : 2 * nxfrm ) end if ! Apply the window wsum = 0.0d0 do i = 1 , nx j = i - 1 wval = win % evaluate ( j ) wsum = wsum + wval xw ( i ) = wval * x ( i ) yw ( i ) = wval * y ( i ) end do fac = nx / wsum ! Pad with zeros if ( nf > nx ) then xw ( nx + 1 : nf ) = 0.0d0 yw ( ny + 1 : nf ) = 0.0d0 end if ! Compute the transforms call dfftf ( nf , xw , w ) call dfftf ( nf , yw , w ) cx = unpack_real_transform ( xw , fac * scale ) cy = unpack_real_transform ( yw , fac * scale ) ! Compute the cross spectrum xfrm = cx * conjg ( cy ) ! Normalize by frequency if ( present ( fs )) then df = frequency_bin_width ( fs , nf ) xfrm = xfrm / df end if end subroutine ! ------------------------------------------------------------------------------ end module","tags":"","loc":"sourcefile\\spectrum_periodogram.f90.html"},{"title":"spectrum_routines.f90 – SPECTRUM","text":"Source Code module spectrum_routines use iso_fortran_env use fftpack implicit none private public :: compute_transform_length public :: frequency_bin_width public :: is_power_of_two public :: next_power_of_two public :: unpack_real_transform public :: cumulative_sum public :: unwrap public :: difference public :: compute_overlap_segment_count public :: overlap public :: remove_mean contains ! ------------------------------------------------------------------------------ pure function compute_transform_length ( n ) result ( rst ) !! Computes the length of the positive half of a discrete Fourier !! transform for a specific signal length. !! !! The length of the discrete Fourier transform is determined as follows. !! !! If n is even, !!  m = \\frac{n}{2} + 1  !! !! else; !!  m = \\frac{n + 1}{2} . integer ( int32 ), intent ( in ) :: n !! The signal length (length of the signal put forth to the Fourier !! transform). integer ( int32 ) :: rst !! The length of the positive half of the discrete Fourier transform. if ( mod ( n , 2 ) == 0 ) then rst = n / 2 + 1 else rst = ( n + 1 ) / 2 end if end function ! ------------------------------------------------------------------------------ pure elemental function frequency_bin_width ( fs , n ) result ( rst ) !! Computes the bin width for a discrete frequency spectrum based !! upon the data sample rate. !! !! The frequency bin width is computed as follows. !! !!  \\Delta f = \\frac{f_{s}}{2 \\left(m - 1 \\right)}  !! !! where m is computed via compute_transform_length. real ( real64 ), intent ( in ) :: fs !! The rate at which the signal was sampled.  The units of this value !! will be the units of the output. integer ( int32 ), intent ( in ) :: n !! The signal length (length of the signal put forth to the !! Fourier transform). real ( real64 ) :: rst !! The frequency bin width. ! Local Variables integer ( int32 ) :: m ! Process m = compute_transform_length ( n ) rst = 0.5d0 * fs / ( m - 1.0d0 ) end function ! ------------------------------------------------------------------------------ pure elemental function is_power_of_two ( n ) result ( rst ) !! Tests to see if a value is an integer power of two. integer ( int32 ), intent ( in ) :: n !! The value to test. logical :: rst !! Returns true if n is a power of two; else, false. ! Process rst = ( n /= 0 ) . and . ( iand ( n , n - 1 ) == 0 ) ! This is equivalent to the C form : n != 0 && ((n & (n - 1)) == 0) end function ! ------------------------------------------------------------------------------ pure elemental function next_power_of_two ( n ) result ( rst ) !! Provides the next higher integer power of two. integer ( int32 ), intent ( in ) :: n !! The value to test. integer ( int32 ) :: rst !! The next power of two higher than n.  If n is already a power of two, !! its value is simply returned.  For instance, if n is set to 128, !! then a value of 7 is returned ( 2&#94;7 = 128  ). ! Process rst = ceiling ( log ( real ( n )) / log ( 2.0 ), int32 ) end function ! ------------------------------------------------------------------------------ pure function unpack_real_transform ( x , fac ) result ( rst ) !! Unpacks a real-valued transform into its complex-valued format. real ( real64 ), intent ( in ) :: x (:) !! The complex-valued signal stored in a real-valued array.  This array !! is assumed to be of length N. real ( real64 ), intent ( in ), optional :: fac !! An optional scaling input.  The default is 1 such that no scaling !! is performed. complex ( real64 ), allocatable , dimension (:) :: rst !! The unpacked complex-valued form of the input array. ! Local Variables integer ( int32 ) :: i , nx , nxfrm real ( real64 ) :: f logical :: is_even ! Initialization nx = size ( x ) is_even = mod ( nx , 2 ) == 0 nxfrm = compute_transform_length ( nx ) if ( present ( fac )) then f = fac else f = 1.0d0 end if allocate ( rst ( nxfrm ), source = ( 0.0d0 , 0.0d0 )) ! Quick Return if ( f == 0.0d0 ) return ! Process if ( f == 1.0d0 ) then rst ( 1 ) = cmplx ( x ( 1 ), 0.0d0 , real64 ) ! the DC term is always real if ( is_even ) then do i = 2 , nxfrm - 1 rst ( i ) = cmplx ( x ( 2 * i - 2 ), x ( 2 * i - 1 ), real64 ) end do rst ( nxfrm ) = cmplx ( x ( nx ), 0.0d0 , real64 ) ! always real for even-lengths else do i = 2 , nxfrm rst ( i ) = cmplx ( x ( 2 * i - 2 ), x ( 2 * i - 1 ), real64 ) end do end if else rst ( 1 ) = f * cmplx ( x ( 1 ), 0.0d0 , real64 ) ! the DC term is always real if ( is_even ) then do i = 2 , nxfrm - 1 rst ( i ) = f * cmplx ( x ( 2 * i - 2 ), x ( 2 * i - 1 ), real64 ) end do rst ( nxfrm ) = f * cmplx ( x ( nx ), 0.0d0 , real64 ) ! always real for even-lengths else do i = 2 , nxfrm rst ( i ) = f * cmplx ( x ( 2 * i - 2 ), x ( 2 * i - 1 ), real64 ) end do end if end if end function ! ------------------------------------------------------------------------------ ! Rounds a number to the required precision (p), but rounds 0.5 down to the ! next lowest integer. pure elemental function round ( x , p ) result ( rst ) ! Arguments real ( real64 ), intent ( in ) :: x integer ( int32 ), intent ( in ) :: p real ( real64 ) :: rst ! Local Variables real ( real64 ) :: scale , val ! Process scale = 1 0.0d0 ** ( - p ) val = x * scale + 0.49d0 rst = floor ( val ) / scale end function ! ------------------------------------------------------------------------------ pure function difference ( x ) result ( rst ) !! Computes the difference between each element in an array. real ( real64 ), intent ( in ) :: x (:) !! The N-element array on which to operate. real ( real64 ), allocatable :: rst (:) !! The N-1 element array containing the difference between each element !! in x. ! Local Variables integer ( int32 ) :: i , n ! Initialization n = size ( x ) if ( n == 0 ) return ! Process if ( n == 1 ) then allocate ( rst ( 1 ), source = 0.0d0 ) return end if allocate ( rst ( n - 1 )) do i = 1 , n - 1 rst ( i ) = x ( i + 1 ) - x ( i ) end do end function ! ------------------------------------------------------------------------------ pure function cumulative_sum ( x ) result ( rst ) !! Computes the cumulative sum of an array. real ( real64 ), intent ( in ) :: x (:) !! The N-element array on which to operate. real ( real64 ), allocatable :: rst (:) !! An N-element array containing the cumulative sum of each element !! in x (e.g. cumulative_sum(x) = [x(1), x(1) + x(2), ...]). ! Local Variables integer ( int32 ) :: i , n ! Initialization n = size ( x ) allocate ( rst ( n )) ! Process rst ( 1 ) = x ( 1 ) do i = 2 , n rst ( i ) = rst ( i - 1 ) + x ( i ) end do end function ! ------------------------------------------------------------------------------ subroutine unwrap ( x , tol ) !! Shifts phase angle arrays to deal with jumps greater than or equal !! to tol by adding multiples of   \\pm 2 \\pi  until !! the jump is less than tol. real ( real64 ), intent ( inout ) :: x (:) !! On input, the phase array.  On output, the unwrapped phase array. real ( real64 ), intent ( in ), optional :: tol !! The tolerance value. ! Parameters real ( real64 ), parameter :: pi = 2.0d0 * acos ( 0.0d0 ) ! Local Variables integer ( int32 ) :: i , n real ( real64 ), allocatable , dimension (:) :: dp , dpcorr real ( real64 ) :: cutoff ! Initialization n = size ( x ) if ( present ( tol )) then cutoff = tol else cutoff = pi end if ! Compute the incremental variations dp = difference ( x ) ! Compute how many time 2*pi we're off, and round to the nearest integer ! with the tie-breaker rounding n+0.5 down to n. dpcorr = round ( dp / ( 2.0d0 * pi ), - 1 ) ! Stop the jump from happening if dp < cutoff do i = 1 , n - 1 if ( abs ( dp ( i )) < cutoff ) dpcorr ( i ) = 0.0d0 end do ! Apply the corrections x ( 2 : n ) = x ( 2 : n ) - ( 2.0d0 * pi ) * cumulative_sum ( dpcorr ) end subroutine ! ------------------------------------------------------------------------------ pure function compute_overlap_segment_count ( n , winsize ) result ( rst ) !! Computes the number of overlapped signals using a nominal 50% overlap. integer ( int32 ), intent ( in ) :: n !! The total length of the signal being overlapped. integer ( int32 ), intent ( in ) :: winsize !! The window size. integer ( int32 ) :: rst !! The number of segments. ! Local Variables integer ( int32 ) :: nxfrm ! Process nxfrm = compute_transform_length ( winsize ) rst = max (( n - 1 ) / nxfrm , 1 ) end function ! ------------------------------------------------------------------------------ pure subroutine overlap ( x , seg , winsize , buffer ) !! Extracts a segment from a signal allowing for a nominally 50% overlap. real ( real64 ), intent ( in ) :: x (:) !! An N-element array containing the entire signal. integer ( int32 ), intent ( in ) :: seg !! The one-based index of the segment to extract. integer ( int32 ), intent ( in ) :: winsize !! The size of the window (segment).  If this value is less than N, the !! end of the segment will be padded with zeros. real ( real64 ), intent ( out ) :: buffer (:) !! A winsize array where the segment will be written. ! Local Variables integer ( int32 ) :: k , nx , nxfrm , nk , noff , i1 , i2 real ( real64 ) :: del ! Initialization nx = size ( x ) nxfrm = compute_transform_length ( winsize ) nk = ( nx - 1 ) / nxfrm if ( nk > 1 ) then del = ( nx - winsize ) / ( nk - 1.0d0 ) else del = 0.0d0 end if ! Slice up the array if ( winsize > nx ) then buffer ( 1 : nx ) = x buffer ( nx + 1 : winsize ) = 0.0d0 else k = seg - 1 noff = int ( k * del + 0.5d0 , int32 ) i1 = noff + 1 i2 = i1 + winsize - 1 buffer = x ( i1 : i2 ) end if ! End return end subroutine ! ****************************************************************************** ! V1.1.3 ADDITIONS ! ------------------------------------------------------------------------------ pure function remove_mean ( x ) result ( rst ) !! Removes the mean offset from the specified data set. real ( real64 ), intent ( in ), dimension (:) :: x !! The array on which to operate. real ( real64 ), allocatable , dimension (:) :: rst !! The data set with its mean removed. ! Local Variables integer ( int32 ) :: n , nw real ( real64 ), allocatable , dimension (:) :: wsave ! Initialization n = size ( x ) nw = 2 * n + 15 allocate ( rst ( n ), source = x ) allocate ( wsave ( nw )) ! Initialize and compute the Fourier transform call dffti ( n , wsave ) call dfftf ( n , rst , wsave ) ! Zero out the DC value and compute the inverse transform rst ( 1 ) = 0.0d0 call dfftb ( n , rst , wsave ) rst = rst / n end function ! ------------------------------------------------------------------------------ end module","tags":"","loc":"sourcefile\\spectrum_routines.f90.html"},{"title":"spectrum_tf.f90 – SPECTRUM","text":"Source Code module spectrum_tf use iso_fortran_env use spectrum_periodogram use spectrum_routines use spectrum_windows implicit none private public :: siso_transfer_function public :: mimo_transfer_function public :: SPCTRM_H1_ESTIMATOR public :: SPCTRM_H2_ESTIMATOR integer ( int32 ), parameter :: SPCTRM_H1_ESTIMATOR = 50002 !! A flag for requesting an H1 transfer function estimator.  An H1 !! estimator is best used when noise is uncorrelated with the input, !! and results in a transfer function estimate of the form !! !!  H_{1} = \\frac{P_{yx}}{P_{xx}} . integer ( int32 ), parameter :: SPCTRM_H2_ESTIMATOR = 50003 !! A flag for requesting an H2 transfer function estimator.  An H2 !! estimator is best used when noise is uncorrelated with the output, !! and results in a transfer function estimate of the form !! !!  H_{2} = \\frac{P_{yy}}{P_{xy}} . contains ! ------------------------------------------------------------------------------ ! REF: ! - https://github.com/giuliovv/tfest/blob/main/tfest/tfest.py ! - https://dsp.stackexchange.com/questions/71811/understanding-the-h1-and-h2-estimators ! - https://github.com/epezent/etfe/blob/main/include/ETFE.hpp pure function siso_transfer_function ( win , x , y , etype , nfft ) result ( rst ) !! Estimates the transfer function for a single-input/single-output !! (SISO) system. class ( window ), intent ( in ) :: win !! The window object. real ( real64 ), intent ( in ) :: x (:) !! An N-element array containing the input signal. real ( real64 ), intent ( in ) :: y (:) !! An N-element array containing the output signal. integer ( int32 ), intent ( in ), optional :: etype !! An optional input that, if supplied, denotes the !! estimator to use.  If no value is specified, an H1 estimator is used. !! The following options are supported. !! !!  - SPCTRM_H1_ESTIMATOR: Uses an H1 estimate. !! !!  - SPCTRM_H2_ESTIMATOR: Uses an H2 estimate. !! !! If an unrecognized value is provided, the routine defaults to an !! H1 estimator. integer ( int32 ), intent ( in ), optional :: nfft !! An optional input that can be used to force the length of each !! individual DFT operation by padding any remaining space with zeros. !! If not supplied, the window size is used to determine the size of !! the DFT. complex ( real64 ), allocatable :: rst (:) !! Returns the complex-valued transfer function estimate. ! Local Variables integer ( int32 ) :: est complex ( real64 ), allocatable , dimension (:) :: pcross real ( real64 ), allocatable , dimension (:) :: pwr ! Initialization if ( present ( etype )) then est = etype else est = SPCTRM_H1_ESTIMATOR end if if ( est /= SPCTRM_H1_ESTIMATOR . and . est /= SPCTRM_H2_ESTIMATOR ) then est = SPCTRM_H1_ESTIMATOR end if ! Process select case ( est ) case ( SPCTRM_H1_ESTIMATOR ) pcross = csd ( win , y , x , nfft = nfft ) pwr = psd ( win , x , nfft = nfft ) allocate ( rst ( size ( pcross ))) rst = ( 0.0d0 , 0.0d0 ) where ( abs ( pwr ) > tiny ( 1.0d0 )) rst = pcross / pwr end where case ( SPCTRM_H2_ESTIMATOR ) pcross = csd ( win , x , y , nfft = nfft ) pwr = psd ( win , y , nfft = nfft ) allocate ( rst ( size ( pcross ))) rst = ( 0.0d0 , 0.0d0 ) where ( abs ( pcross ) > tiny ( 1.0d0 )) rst = pwr / pcross end where end select end function ! ------------------------------------------------------------------------------ pure function mimo_transfer_function ( win , x , y , etype , nfft ) result ( rst ) !! Estimates the transfer function matrix for a multiple-input/ !! multiple-output (MIMO) system. !! !! The input signal matrix is expected to have dimensions (n, nin) where !! the second index denotes the input channel.  The output signal matrix is !! expected to have dimensions (n, nout) where the second index denotes the !! output channel.  The returned transfer matrix has dimensions !! (nout, nin, m) where m is the transform length. class ( window ), intent ( in ) :: win !! The window object. real ( real64 ), intent ( in ) :: x (:, :) !! An N-by-NIN array containing the input signals. real ( real64 ), intent ( in ) :: y (:, :) !! An N-by-NOUT array containing the output signals. integer ( int32 ), intent ( in ), optional :: etype !! An optional input that, if supplied, denotes the estimator to use. !! Supported values are the same as for SISO transfer estimates. integer ( int32 ), intent ( in ), optional :: nfft !! An optional input that can be used to force the length of each !! individual DFT operation by padding any remaining space with zeros. complex ( real64 ), allocatable :: rst (:, :, :) !! Returns the complex-valued transfer function estimate matrix. ! Local Variables integer ( int32 ) :: est , nx , ny , nin , nout , i , j , nf complex ( real64 ), allocatable , dimension (:) :: pcross real ( real64 ), allocatable , dimension (:) :: pwr ! Initialization nx = size ( x , 1 ) ny = size ( y , 1 ) nin = size ( x , 2 ) nout = size ( y , 2 ) if ( present ( etype )) then est = etype else est = SPCTRM_H1_ESTIMATOR end if if ( est /= SPCTRM_H1_ESTIMATOR . and . est /= SPCTRM_H2_ESTIMATOR ) then est = SPCTRM_H1_ESTIMATOR end if if ( nx /= ny . or . nin < 1 . or . nout < 1 ) return if ( present ( nfft )) then nf = nfft else nf = win % size end if allocate ( rst ( nout , nin , compute_transform_length ( nf ))) rst = ( 0.0d0 , 0.0d0 ) ! Process select case ( est ) case ( SPCTRM_H1_ESTIMATOR ) do j = 1 , nout do i = 1 , nin pcross = csd ( win , y (:, j ), x (:, i ), nfft = nfft ) pwr = psd ( win , x (:, i ), nfft = nfft ) where ( abs ( pwr ) > tiny ( 1.0d0 )) rst ( j , i , :) = pcross / pwr elsewhere rst ( j , i , :) = ( 0.0d0 , 0.0d0 ) end where end do end do case ( SPCTRM_H2_ESTIMATOR ) do j = 1 , nout do i = 1 , nin pcross = csd ( win , x (:, i ), y (:, j ), nfft = nfft ) pwr = psd ( win , y (:, j ), nfft = nfft ) where ( abs ( pcross ) > tiny ( 1.0d0 )) rst ( j , i , :) = pwr / pcross elsewhere rst ( j , i , :) = ( 0.0d0 , 0.0d0 ) end where end do end do end select end function ! ------------------------------------------------------------------------------ end module","tags":"","loc":"sourcefile\\spectrum_tf.f90.html"},{"title":"spectrum_windows.f90 – SPECTRUM","text":"Source Code module spectrum_windows use iso_fortran_env implicit none private public :: window public :: window_function public :: rectangular_window public :: hann_window public :: hamming_window public :: welch_window public :: blackman_harris_window public :: flat_top_window real ( real64 ), parameter :: pi = 2.0d0 * acos ( 0.0d0 ) type , abstract :: window !! Defines the structure of a window. integer ( int32 ), public :: size = 0 !! The window size. contains procedure ( window_function ), public , deferred , pass :: evaluate end type interface pure function window_function ( this , bin ) result ( rst ) !! Evaluates the window function. use iso_fortran_env , only : real64 , int32 import window class ( window ), intent ( in ) :: this !! The window object. integer ( int32 ), intent ( in ) :: bin !! The index or bin number [0, n], where n is the window size. real ( real64 ) :: rst !! The function value. end function end interface !> @brief Defines a rectangular window. type , extends ( window ) :: rectangular_window !! Defines a rectangular window. contains procedure , public :: evaluate => rw_eval end type type , extends ( window ) :: hann_window !! Defines a Hann window. !! !!  w(j) = \\frac{1}{2} \\left( 1 - \\cos \\left( \\frac{2 \\pi j}{n} \\right) \\right) . !! !! See Also !! !! - [Wikipedia](https://en.wikipedia.org/wiki/Window_function) contains procedure , public :: evaluate => hann_eval end type type , extends ( window ) :: hamming_window !! Defines a Hamming window. !! !!  w(j) = 0.54 - 0.46 \\cos \\left( \\frac{2 \\pi j}{n} \\right)  !! !! See Also !! !! - [Wikipedia](https://en.wikipedia.org/wiki/Window_function) contains procedure , public :: evaluate => hamming_eval end type type , extends ( window ) :: welch_window !! Defines a Welch window. !! !!  w(j) = 1 - \\left( \\frac{j - \\frac{n}{2} }{ \\frac{n}{2} } \\right)&#94;2  !! !! See Also !! !! - [Wikipedia](https://en.wikipedia.org/wiki/Window_function) contains procedure , public :: evaluate => welch_eval end type type , extends ( window ) :: blackman_harris_window !! Defines a Blackman-Harris window. !! !!  w(j) = 0.3635819 - 0.4891775 \\cos \\left( \\frac{2 \\pi j}{n} \\right) !! + 0.1365995 \\cos \\left( \\frac{4 \\pi j}{n} \\right) - 0.0106411 !! \\cos \\left( \\frac{6 \\pi j}{n} \\right)  !! !! See Also !! !! - [Wikipedia](https://en.wikipedia.org/wiki/Window_function) contains procedure , public :: evaluate => bhw_eval end type type , extends ( window ) :: flat_top_window !! Defines a flat-top window. !! !!  w(j) = 0.21557895 - !! 0.41663158 \\cos \\left( \\frac{2 \\pi j}{N} \\right) + !! 0.277263158 \\cos \\left( \\frac{4 \\pi j}{N} \\right) - !! 0.083578947 \\cos \\left( \\frac{6 \\pi j}{N} \\right)  + !! 0.006947368 \\cos \\left( \\frac{8 \\pi j}{N} \\right)  !! !! See Also !! !! - [Wikipedia](https://en.wikipedia.org/wiki/Window_function) contains procedure , public :: evaluate => ftw_eval end type contains ! ------------------------------------------------------------------------------ pure function rw_eval ( this , bin ) result ( rst ) !! Evaluates the window function. class ( rectangular_window ), intent ( in ) :: this !! The rectangular_window object. integer ( int32 ), intent ( in ) :: bin !! The index or bin number [0, n], where n is the window size. real ( real64 ) :: rst !! The function value. rst = 1.0d0 end function ! ------------------------------------------------------------------------------ pure function hann_eval ( this , bin ) result ( rst ) !! Evaluates the window function. class ( hann_window ), intent ( in ) :: this !! The hann_window object. integer ( int32 ), intent ( in ) :: bin !! The index or bin number [0, n], where n is the window size. real ( real64 ) :: rst !! The function value. rst = 0.5d0 * ( 1.0d0 - cos ( 2.0d0 * pi * bin / this % size )) end function ! ------------------------------------------------------------------------------ pure function hamming_eval ( this , bin ) result ( rst ) !! Evaluates the window function. class ( hamming_window ), intent ( in ) :: this !! The hamming_window object. integer ( int32 ), intent ( in ) :: bin !! The index or bin number [0, n], where n is the window size. real ( real64 ) :: rst !! The function value. rst = 0.54d0 - 0.46d0 * cos ( 2.0d0 * pi * bin / this % size ) end function ! ------------------------------------------------------------------------------ pure function welch_eval ( this , bin ) result ( rst ) !! Evaluates the window function. class ( welch_window ), intent ( in ) :: this !! The welch_window object. integer ( int32 ), intent ( in ) :: bin !! The index or bin number [0, n], where n is the window size. real ( real64 ) :: rst !! The function value. real ( real64 ) :: halfsize halfsize = 0.5d0 * this % size rst = 1.0d0 - (( bin - halfsize ) / halfsize ) ** 2 end function ! ------------------------------------------------------------------------------ pure function bhw_eval ( this , bin ) result ( rst ) !! Evaluates the window function. class ( blackman_harris_window ), intent ( in ) :: this !! The blackman_harris_window object. integer ( int32 ), intent ( in ) :: bin !! The index or bin number [0, n], where n is the window size. real ( real64 ) :: rst !! The function value. rst = 0.35875d0 - & 0.48829d0 * cos ( 2.0d0 * pi * bin / this % size ) + & 0.14128d0 * cos ( 4.0d0 * pi * bin / this % size ) - & 0.01168d0 * cos ( 6.0d0 * pi * bin / this % size ) end function ! ------------------------------------------------------------------------------ pure function ftw_eval ( this , bin ) result ( rst ) !! Evaluates the window function. class ( flat_top_window ), intent ( in ) :: this !! The flat_top_window object. integer ( int32 ), intent ( in ) :: bin !! The index or bin number [0, n], where n is the window size. real ( real64 ) :: rst !! The function value. real ( real64 ), parameter :: a0 = 0.21557895d0 real ( real64 ), parameter :: a1 = 0.41663158d0 real ( real64 ), parameter :: a2 = 0.277263158d0 real ( real64 ), parameter :: a3 = 8.3578947d-2 real ( real64 ), parameter :: a4 = 6.947368d-3 real ( real64 ) :: arg arg = pi * bin / this % size rst = a0 - a1 * cos ( 2.0d0 * arg ) + a2 * cos ( 4.0d0 * arg ) - & a3 * cos ( 6.0d0 * arg ) + a4 * cos ( 8.0d0 * arg ) end function ! ------------------------------------------------------------------------------ end module","tags":"","loc":"sourcefile\\spectrum_windows.f90.html"},{"title":"spectrum_diff.f90 – SPECTRUM","text":"Source Code ! REF: ! - https://ejde.math.txstate.edu/conf-proc/21/k3/knowles.pdf ! - https://arxiv.org/pdf/2009.01911.pdf module spectrum_diff use iso_fortran_env use blas use linalg use lapack , only : dgesv implicit none private public :: finite_difference public :: tvr_derivative public :: stencil_diff_5 public :: stencil_second_diff_5 public :: filter_diff interface finite_difference module procedure :: finite_difference_1 module procedure :: finite_difference_2 end interface interface finite_difference_driver module procedure :: finite_difference_driver_1 module procedure :: finite_difference_driver_2 end interface contains ! ------------------------------------------------------------------------------ pure subroutine finite_difference_driver_1 ( dt , x , dxdt ) ! Arguments real ( real64 ), intent ( in ) :: dt real ( real64 ), intent ( in ), dimension (:) :: x real ( real64 ), intent ( out ), dimension (:) :: dxdt ! Local Variables integer ( int32 ) :: i , n ! Process n = size ( x ) if ( n == 0 ) return if ( n == 1 ) then dxdt = 0.0d0 return end if dxdt ( 1 ) = ( x ( 2 ) - x ( 1 )) / dt do i = 2 , n - 1 dxdt ( i ) = 0.5d0 * ( x ( i + 1 ) - x ( i - 1 )) / dt end do dxdt ( n ) = ( x ( n ) - x ( n - 1 )) / dt end subroutine ! ------------------------------------------------------------------------------ pure subroutine finite_difference_driver_2 ( t , x , dxdt ) ! Arguments real ( real64 ), intent ( in ), dimension (:) :: t , x real ( real64 ), intent ( out ), dimension (:) :: dxdt ! Local Variables integer ( int32 ) :: i , n ! Process n = size ( x ) if ( n == 0 ) return if ( n == 1 ) then dxdt = 0.0d0 return end if dxdt ( 1 ) = ( x ( 2 ) - x ( 1 )) / ( t ( 2 ) - t ( 1 )) do i = 2 , n - 1 dxdt ( i ) = ( x ( i + 1 ) - x ( i - 1 )) / ( t ( i + 1 ) - t ( i - 1 )) end do dxdt ( n ) = ( x ( n ) - x ( n - 1 )) / ( t ( n ) - t ( n - 1 )) end subroutine ! ------------------------------------------------------------------------------ pure function finite_difference_1 ( dt , x ) result ( rst ) !! Estimates the derivative of a data set by means of a naive !! implementation of a finite difference scheme based upon central !! differences. real ( real64 ), intent ( in ) :: dt !! The time step between data points. real ( real64 ), intent ( in ), dimension (:) :: x !! An N-element array containing the data whose derivative is to be !! estimated. real ( real64 ), allocatable , dimension (:) :: rst !! An N-element array containing the derivative estimate. ! Local Variables integer ( int32 ) :: n ! Initialization n = size ( x ) allocate ( rst ( n )) ! Process call finite_difference_driver ( dt , x , rst ) end function ! ------------------------------------------------------------------------------ pure function finite_difference_2 ( t , x ) result ( rst ) !! Computes an estimate to the derivative of an evenly-sampled data !! set using total variation regularization. real ( real64 ), intent ( in ), dimension (:) :: t !! An N-element array containing the time points at which x was sampled. real ( real64 ), intent ( in ), dimension (:) :: x !! An N-element array containing the data whose derivative is to be !! estimated. real ( real64 ), allocatable , dimension (:) :: rst !! An N-element array containing the derivative estimate. ! Local Variables integer ( int32 ) :: n ! Initialization n = size ( t ) ! Input Checking if ( size ( x ) /= n ) return ! Memory Allocation allocate ( rst ( n )) ! Process call finite_difference_driver ( t , x , rst ) end function ! ****************************************************************************** ! TOTAL VARIATION REGULARIZATION ! ------------------------------------------------------------------------------ ! REF: https://oliver-k-ernst.medium.com/how-to-differentiate-noisy-signals-2baf71b8bb65 ! https://github.com/smrfeld/Total-Variation-Regularization-Derivative-Python/blob/main/python/diff_tvr.py ! https://github.com/florisvb/PyNumDiff/blob/master/pynumdiff/total_variation_regularization/__chartrand_tvregdiff__.py ! Constructs the N-by-N+1 D matrix: !          | -1     1         | ! D = 1/dx |  0     -1      1 | !          |  0     0      -1 | pure subroutine make_d_full ( dx , d ) ! Arguments real ( real64 ), intent ( in ) :: dx real ( real64 ), intent ( out ), dimension (:,:) :: d ! Local Variables integer ( int32 ) :: j , n real ( real64 ) :: idx ! Process n = size ( d , 1 ) idx = 1.0d0 / dx d = 0.0d0 do j = 1 , n + 1 if ( j > 1 ) d ( j - 1 , j ) = idx if ( j <= n ) d ( j , j ) = - idx end do end subroutine ! ------------------------------------------------------------------------------ ! Constructs the N-by-N+1 A matrix. pure subroutine make_a_full ( dx , a ) ! Arguments real ( real64 ), intent ( in ) :: dx real ( real64 ), intent ( out ), dimension (:,:) :: a ! Local Variables integer ( int32 ) :: j , n real ( real64 ) :: hdx ! Process n = size ( a , 1 ) hdx = 0.5d0 * dx do j = 1 , n + 1 if ( j == 1 ) then a (:, j ) = hdx else if ( j > 1 ) a ( j - 1 , j ) = hdx if ( j <= n ) a ( j :, j ) = dx end if end do end subroutine ! ------------------------------------------------------------------------------ ! Constructs the N-by-N E matrix.  The matrix is a diagonal matrix with only the ! diagonal stored. subroutine make_e ( d , u , e ) ! Arguments real ( real64 ), intent ( in ), dimension (:,:) :: d real ( real64 ), intent ( in ), dimension (:) :: u real ( real64 ), intent ( out ), dimension (:) :: e ! Local Variables integer ( int32 ) :: j , n , n1 real ( real64 ) :: eps ! Process eps = sqrt ( epsilon ( eps )) n = size ( d , 1 ) n1 = n + 1 call dgemv ( \"N\" , n , n1 , 1.0d0 , d , n , u , 1 , 0.0d0 , e , 1 ) do j = 1 , n e ( j ) = 1.0d0 / sqrt ( e ( j ) ** 2 + eps ) end do end subroutine ! ------------------------------------------------------------------------------ function tvr_diff_small ( alpha , dt , x , maxiter , tol , niter ) result ( dxdt ) real ( real64 ), intent ( in ) :: alpha ! variational parameter real ( real64 ), intent ( in ) :: dt ! time step real ( real64 ), intent ( in ), dimension (:) :: x ! data array to differentiate integer ( int32 ), intent ( in ) :: maxiter ! max # of iterations real ( real64 ), intent ( in ) :: tol ! tolerance on change in gradient integer ( int32 ), intent ( out ) :: niter ! # of iterations taken real ( real64 ), allocatable , dimension (:) :: dxdt ! derivative dx/dt ! Local Variables integer ( int32 ) :: i , n , n1 , flag integer ( int32 ), allocatable , dimension (:) :: ipiv real ( real64 ) :: offset , nrm , nrmold real ( real64 ), allocatable , dimension (:,:) :: d , a , dte , l , ata , h real ( real64 ), allocatable , dimension (:) :: e , u , atb , atau , lu , g ! Initialization n = size ( x ) n1 = n + 1 offset = x ( 1 ) nrmold = huge ( nrmold ) ! Memory Allocations allocate ( & d ( n , n1 ), & a ( n , n1 ), & e ( n ), & u ( n1 ), & atb ( n ), & dte ( n1 , n ), & l ( n1 , n1 ), & ata ( n1 , n1 ), & atau ( n1 ), & lu ( n1 ), & g ( n1 ), & h ( n1 , n1 ), & ipiv ( n1 ), & dxdt ( n ) & ) ! Construct matrices call make_d_full ( dt , d ) call make_a_full ( dt , a ) call dgemm ( \"T\" , \"N\" , n1 , n1 , n , 1.0d0 , a , n , a , n , 0.0d0 , ata , n1 ) ! A**T * A ! Provide a first estimate of the derivative u ( 1 ) = 0.0d0 u ( 2 :) = finite_difference ( dt , x ) ! Precompute A**T * (X(1) - X) call dgemv ( \"T\" , n , n1 , 1.0d0 , a , n , offset - x , 1 , 0.0d0 , atb , 1 ) ! Iteration Process do i = 1 , maxiter ! Compute E and L call make_e ( d , u , e ) call diag_mtx_mult (. false ., . true ., dt , e , d , 0.0d0 , dte ) ! dt * D**T * E call dgemm ( \"N\" , \"N\" , n1 , n1 , n , 1.0d0 , dte , n1 , d , n , 0.0d0 , l , n1 ) ! L = (dx * D**T * E) * D ! Compute the gradient call dgemv ( \"N\" , n1 , n1 , 1.0d0 , ata , n1 , u , 1 , 0.0d0 , atau , 1 ) call dgemv ( \"N\" , n1 , n1 , alpha , l , n1 , u , 1 , 0.0d0 , lu , 1 ) g = atau + atb + lu ! Compute H h = ata + alpha * l ! Solve H * s = g, for s - stored in g call dgesv ( n1 , 1 , h , n1 , ipiv , g , n1 , flag ) if ( flag /= 0 ) return ! Check the solution nrm = norm2 ( g ) if ( abs ( nrm - nrmold ) < tol ) exit nrmold = nrm ! Update the derivative estimate u = u - g end do niter = min ( i , maxiter ) ! Extract the computed derivative dxdt = u ( 1 : n ) end function ! ------------------------------------------------------------------------------ function tvr_derivative ( dt , x , alpha , maxiter , tol , use_sparse , niter ) result ( rst ) !! Computes an estimate to the derivative of an evenly-sampled data !! set using total variation regularization. !! !! This implementation solves the augmented dense formulation using an !! integration matrix and a first-difference regularization operator. The !! dense formulation uses the physical time step in its difference matrix !! and allocates dense matrices whose storage grows quadratically with the !! number of samples. !! !! When use_sparse is true, this routine dispatches to !! tvr_derivative_sparse. That solver uses a different data-fitting term, !! a second-difference operator, physical curvature scaling, and normalized !! IRLS weights. Consequently, alpha values are solver-specific and should !! not be compared directly. !! !! See Also !! !! - van Breugel, Floris & Brunton, Bingni & Kutz, J.. (2020). Numerical !!   differentiation of noisy data: A unifying multi-objective optimization !!   framework. real ( real64 ), intent ( in ) :: dt !! The time step between data points. real ( real64 ), intent ( in ), dimension (:) :: x !! An N-element array containing the data whose derivative is !! to be estimated. real ( real64 ), intent ( in ) :: alpha !! The regularization parameter. integer ( int32 ), intent ( in ), optional :: maxiter !! The maximum number of iterations to allow.  The default is 20 !! iterations. real ( real64 ), intent ( in ), optional :: tol !! The convergence tolerance to use.  The tolerance is !! applied to the change in the update measure. The dense solver uses !! an absolute Euclidean norm, while the sparse solver uses a relative !! Euclidean norm. The default is 1e-3. logical , intent ( in ), optional :: use_sparse !! True if the sparse solver should be used vs. the dense solver.  This !! is highly recommended when N is larger than ~1000.  The default is !! true such that the sparse solver is used. The sparse solver has !! linear storage growth and is preferred for large data sets. integer ( int32 ), intent ( out ), optional :: niter !! The number of iterations actually performed. real ( real64 ), allocatable , dimension (:) :: rst !! An N-element array containing the estimate of the derivative. ! Local Variables logical :: sparse integer ( int32 ) :: mi , ni real ( real64 ) :: gtol ! Initialization if ( present ( maxiter )) then mi = maxiter else mi = 20 end if if ( present ( tol )) then gtol = tol else gtol = 1.0d-3 end if if ( present ( use_sparse )) then sparse = use_sparse else sparse = . true . end if ! Process if ( sparse ) then rst = tvr_derivative_sparse ( dt , x , alpha , maxiter = mi , tol = gtol , & niter = ni ) else rst = tvr_diff_small ( alpha , dt , x , mi , gtol , ni ) end if if ( present ( niter )) niter = ni end function ! ------------------------------------------------------------------------------ function tvr_derivative_sparse ( dt , x , alpha , maxiter , tol , niter ) result ( rst ) !! Computes a total-variation-regularized derivative using sparse matrices. !! !! This routine regularizes the finite-difference derivative with a sparse !! second-difference operator and uses the derivative itself as the data !! fit. The second difference is scaled by dt**2 to represent physical !! curvature, then normalized before the IRLS weights are formed to keep !! the sparse systems well conditioned. The resulting iteratively !! reweighted systems contain at most five non-zero diagonals, so memory !! use grows linearly with the number of samples. !! !! This is a scalable alternative to tvr_derivative, not an algebraically !! equivalent sparse implementation of it. The two routines use different !! data-fitting and regularization formulations. The sparse alpha is a !! normalized regularization parameter and should not be compared directly !! with the dense alpha. real ( real64 ), intent ( in ) :: dt !! The time step between data points. real ( real64 ), intent ( in ), dimension (:) :: x !! An N-element array containing the data whose derivative is !! to be estimated. real ( real64 ), intent ( in ) :: alpha !! The normalized regularization parameter. Larger values produce a !! smoother derivative estimate. Its value is not directly comparable !! with the alpha parameter used by the dense formulation. integer ( int32 ), intent ( in ), optional :: maxiter !! The maximum number of reweighting iterations. The default is 20. real ( real64 ), intent ( in ), optional :: tol !! The relative convergence tolerance applied to the derivative update !! norm. The default is 1e-3. integer ( int32 ), intent ( out ), optional :: niter !! The number of iterations actually performed. real ( real64 ), allocatable , dimension (:) :: rst !! An N-element array containing the estimate of the derivative. integer ( int32 ) :: i , j , k , n , nrows , max_iterations , iterations real ( real64 ) :: convergence_tol , change , curvature_scale , system_scale real ( real64 ) :: data_coefficient , regularization_coefficient , dt2 real ( real64 ), allocatable :: estimate (:), candidate (:), weights (:), & second_difference (:), rhs (:) type ( csr_matrix ) :: d , h n = size ( x ) allocate ( rst ( n )) if ( n == 0 ) return if ( n < 3 . or . dt == 0.0d0 . or . alpha < 0.0d0 ) then rst = finite_difference ( dt , x ) if ( present ( niter )) niter = 0 return end if if ( present ( maxiter )) then max_iterations = maxiter else max_iterations = 20 end if if ( present ( tol )) then convergence_tol = tol else convergence_tol = 1.0d-3 end if if ( max_iterations < 1 ) then rst = finite_difference ( dt , x ) if ( present ( niter )) niter = 0 return end if nrows = n - 2 allocate ( estimate ( n ), candidate ( n ), rhs ( n ), weights ( nrows ), & second_difference ( nrows )) estimate = finite_difference ( dt , x ) rhs = estimate d = create_empty_csr_matrix ( nrows , n , 3 * nrows ) d % row_indices ( 1 ) = 1 do i = 1 , nrows k = 3 * ( i - 1 ) + 1 d % column_indices ( k : k + 2 ) = [ i , i + 1 , i + 2 ] d % values ( k : k + 2 ) = [ 1.0d0 , - 2.0d0 , 1.0d0 ] d % row_indices ( i + 1 ) = k + 3 end do iterations = 0 dt2 = dt ** 2 do i = 1 , max_iterations second_difference = matmul ( d , estimate ) / dt2 curvature_scale = max ( 1.0d0 , maxval ( abs ( second_difference ))) weights = 1.0d0 / sqrt (( second_difference / curvature_scale ) ** 2 + & sqrt ( epsilon ( 1.0d0 ))) ! Curvature is normalized before IRLS weighting. This preserves the ! relative weighting while avoiding large coefficients for flat data. system_scale = max ( 1.0d0 , alpha * maxval ( weights )) data_coefficient = 1.0d0 / system_scale regularization_coefficient = alpha / system_scale h = create_empty_csr_matrix ( n , n , 5 * n - 6 ) h % row_indices ( 1 ) = 1 k = 1 do j = 1 , n do while ( k <= h % row_indices ( 1 ) - 1 ) k = k + 1 end do call fill_sparse_system_row ( j , weights , data_coefficient , & regularization_coefficient , h , k ) h % row_indices ( j + 1 ) = k end do candidate = sparse_direct_solve ( h , data_coefficient * rhs ) change = norm2 ( candidate - estimate ) / max ( norm2 ( estimate ), 1.0d0 ) estimate = candidate iterations = i if ( change < convergence_tol ) exit end do rst = estimate if ( present ( niter )) niter = iterations end function ! ------------------------------------------------------------------------------ pure subroutine fill_sparse_system_row ( row , weights , data_coefficient , & regularization_coefficient , h , offset ) integer ( int32 ), intent ( in ) :: row real ( real64 ), intent ( in ) :: weights (:), data_coefficient , & regularization_coefficient type ( csr_matrix ), intent ( inout ) :: h integer ( int32 ), intent ( inout ) :: offset integer ( int32 ) :: col , first_row , last_row , difference_row real ( real64 ) :: value first_row = max ( 1 , row - 2 ) last_row = min ( size ( weights ), row ) do col = first_row , last_row + 2 value = 0.0d0 do difference_row = first_row , last_row value = value + second_difference_coefficient ( difference_row , col ) * & second_difference_coefficient ( difference_row , row ) * & weights ( difference_row ) end do value = value * regularization_coefficient if ( col == row ) value = value + data_coefficient h % column_indices ( offset ) = col h % values ( offset ) = value offset = offset + 1 end do end subroutine ! ------------------------------------------------------------------------------ pure function second_difference_coefficient ( row , col ) result ( value ) integer ( int32 ), intent ( in ) :: row , col real ( real64 ) :: value select case ( col - row ) case ( 0 ) value = 1.0d0 case ( 1 ) value = - 2.0d0 case ( 2 ) value = 1.0d0 case default value = 0.0d0 end select end function ! ****************************************************************************** ! V1.1.2 ADDITIONS ! ------------------------------------------------------------------------------ pure function stencil_diff_5 ( dt , x ) result ( rst ) !! Utilizes a 5-point stencil to estimate the derivative of a data set. !! !! See Also !! !! - [Wikipedia](https://en.wikipedia.org/wiki/Five-point_stencil) real ( real64 ), intent ( in ) :: dt !! The time step between data points. real ( real64 ), intent ( in ), dimension (:) :: x !! An N-element array containing the data whose derivative is to be !! estimated. real ( real64 ), allocatable , dimension (:) :: rst !! An N-element array containing the derivative estimate. ! Local Variables integer ( int32 ) :: i , n ! Initialization n = size ( x ) allocate ( rst ( n )) ! Process ! Step in and out of the problem via finite differences; else, use ! a 5-point stencil of the form: ! ! f'(x) = (-f(x+2h) + 8f(x+h) - 8f(x-h) + f(x-2h)) / (12h) rst ( 1 ) = ( x ( 2 ) - x ( 1 )) / dt rst ( 2 ) = ( x ( 3 ) - x ( 2 )) / dt do i = 3 , n - 2 rst ( i ) = ( - x ( i + 2 ) + 8.0d0 * ( x ( i + 1 ) - x ( i - 1 )) + x ( i - 2 )) / & ( 1 2.0d0 * dt ) end do rst ( n - 1 ) = ( x ( n - 1 ) - x ( n - 2 )) / dt rst ( n ) = ( x ( n ) - x ( n - 1 )) / dt end function ! ------------------------------------------------------------------------------ pure function stencil_second_diff_5 ( dt , x ) result ( rst ) !! Utilizes a 5-point stencil to estimate the second derivative of a data !! set. !! !! See Also !! !! - [Wikipedia](https://en.wikipedia.org/wiki/Five-point_stencil) real ( real64 ), intent ( in ) :: dt !! The time step between data points. real ( real64 ), intent ( in ), dimension (:) :: x !! An N-element array containing the data whose derivative is to be !! estimated. real ( real64 ), allocatable , dimension (:) :: rst !! An N-element array containing the derivative estimate. ! Local Variables integer ( int32 ) :: i , n real ( real64 ) :: h2 ! Initialization n = size ( x ) allocate ( rst ( n )) ! Process ! Step in and out of the problem via finite differences; else, use ! a 5-point stencil of the form: ! ! f\"(x) = (-f(x+2h) + 16f(x+h) - 30f(x) + 16f(x-h) - f(x-2h)) / (12h**2) h2 = dt ** 2 rst ( 1 ) = ( x ( 3 ) - 2.0d0 * x ( 2 ) + x ( 1 )) / h2 rst ( 2 ) = ( x ( 4 ) - 2.0d0 * x ( 3 ) + x ( 2 )) / h2 do i = 3 , n - 2 rst ( i ) = ( - x ( i + 2 ) - 3.0d1 * x ( i ) + 1.6d1 * ( x ( i + 1 ) + x ( i - 1 )) - & x ( i - 2 )) / ( 1.2d1 * h2 ) end do rst ( n - 1 ) = ( x ( n - 1 ) - 2.0d0 * x ( n - 2 ) + x ( n - 3 )) / h2 rst ( n ) = ( x ( n ) - 2.0d0 * x ( n - 1 ) + x ( n - 2 )) / h2 end function ! ****************************************************************************** ! V1.1.3 ADDITIONS ! ------------------------------------------------------------------------------ pure function filter_diff ( dt , x , fc ) result ( rst ) !! Estimates the derivative of a signal by utilization of a second-order !! system as a filter. real ( real64 ), intent ( in ) :: dt !! The time step between data points. real ( real64 ), intent ( in ), dimension (:) :: x !! An N-element array containing the data whose derivative is to be !! estimated. real ( real64 ), intent ( in ) :: fc !! The filter cutoff frequency, in Hz. real ( real64 ), allocatable , dimension (:,:) :: rst !! An N-element array containing the filtered signal in the first column !! and the derivative estimate in the second. ! Parameters real ( real64 ), parameter :: pi = 2.0d0 * acos ( 0.0d0 ) real ( real64 ), parameter :: zeta = 0.5d0 * sqrt ( 2.0d0 ) ! Local Variables integer ( int32 ) :: i , n real ( real64 ) :: fs , wn ! Initialization n = size ( x ) fs = 1.0d0 / dt wn = 2.0d0 * pi * fc ! Input Checking if ( fc >= 0.5d0 * fs . or . fc <= 0.0d0 ) return ! Memory Allocations allocate ( rst ( n , 2 )) ! Define the initial conditions rst ( 1 , 1 ) = x ( 1 ) ! output initial value is equivalent to the original value rst ( 1 , 2 ) = ( x ( 2 ) - x ( 1 )) / dt ! finite difference estimate of the first point ! Perform the integration using Euler's method do i = 2 , n ! Predictor Stage (Explicit Method) rst ( i ,:) = rst ( i - 1 ,:) + dt * fcn ( rst ( i - 1 ,:), x ( i - 1 ), wn , zeta ) ! Corrector Stage (Implicit Method) rst ( i ,:) = rst ( i - 1 ,:) + dt * fcn ( Rst ( i ,:), x ( i ), wn , zeta ) end do end function ! ---------- pure function fcn ( x , y , wn , zeta ) result ( dxdt ) !! The second-order equations of motion. real ( real64 ), intent ( in ) :: x ( 2 ) !! The current state variables. real ( real64 ), intent ( in ) :: y !! The current value of the original signal. real ( real64 ), intent ( in ) :: wn !! The second-order system natural frequency, in rad/s. real ( real64 ), intent ( in ) :: zeta !! The second-order system damping ratio. real ( real64 ) :: dxdt ( 2 ) !! The output derivative values. ! Equation of Motion: ! x\" + 2 * zeta * wn * x' + wn**2 * x = wn**2 * y dxdt ( 1 ) = x ( 2 ) dxdt ( 2 ) = wn ** 2 * ( y - x ( 1 )) - 2.0d0 * zeta * wn * x ( 2 ) end function ! ------------------------------------------------------------------------------ end module","tags":"","loc":"sourcefile\\spectrum_diff.f90.html"},{"title":"spectrum_convolve.f90 – SPECTRUM","text":"Source Code module spectrum_convolve use iso_fortran_env use fftpack implicit none private public :: convolve public :: SPCTRM_FULL_CONVOLUTION public :: SPCTRM_CENTRAL_CONVOLUTION integer ( int32 ), parameter :: SPCTRM_FULL_CONVOLUTION = 50000 !! A flag for requesting a full convolution. integer ( int32 ), parameter :: SPCTRM_CENTRAL_CONVOLUTION = 50001 !! A flag for requesting the central portion of the convolution that is !! the same length as the input signal. contains ! ------------------------------------------------------------------------------ pure function convolve ( x , y , method ) result ( rst ) !! Computes the convolution of a signal and kernel. real ( real64 ), intent ( in ) :: x (:) !! The N-element signal. real ( real64 ), intent ( in ) :: y (:) !! The M-element kernel. integer ( int32 ), intent ( in ), optional :: method !! An optional input that dictates the expected !! convolution result.  The following options are available. !! !! - SPCTRM_FULL_CONVOLUTION: The full convolution results are provided, !!     including the portions polluted courtesy of the zero-padding and !!     the corresponding wrap-around effects.  The length of this output !!     is N + M - 1. !! !!   SPCTRM_CENTRAL_CONVOLUTION: The N-element result containing the !!     convolved signal not poluted by the zero-padding and !!     corresponding wrap-around effects. real ( real64 ), allocatable :: rst (:) !! The convolved result. ! Local Variables integer ( int32 ) :: mth , n1 , n2 real ( real64 ), allocatable :: temp (:) complex ( real64 ), allocatable :: xmod (:), ymod (:) ! Initialization if ( present ( method )) then mth = method else mth = SPCTRM_FULL_CONVOLUTION end if ! Input Checking if ( mth /= SPCTRM_FULL_CONVOLUTION . and . & mth /= SPCTRM_CENTRAL_CONVOLUTION ) & then ! Reset mth = SPCTRM_FULL_CONVOLUTION end if ! Prepare the signals call prepare_conv ( x , y , xmod , ymod , n1 , n2 ) ! Compute the convolution if ( mth == SPCTRM_CENTRAL_CONVOLUTION ) then call convolve_driver ( xmod , ymod , 1 , temp ) rst = temp ( n1 : n2 ) else call convolve_driver ( xmod , ymod , 1 , rst ) end if end function ! ------------------------------------------------------------------------------ ! Prepares two signals for convolution. ! ! - x: The original signal of length N. ! - y: The original response signal of length M where M <= N. ! - xmod: The padded X signal of length M + N - 1. ! - ymod: The padded Y signal of length M + N - 1. ! - n2: The ending index of the unspoiled data pure subroutine prepare_conv ( x , y , xmod , ymod , n1 , n2 ) ! Arguments real ( real64 ), intent ( in ) :: x (:), y (:) complex ( real64 ), intent ( out ), allocatable :: xmod (:), ymod (:) integer ( int32 ), intent ( out ) :: n1 , n2 ! Parameters complex ( real64 ), parameter :: zero = ( 0.0d0 , 0.0d0 ) ! Local Variables integer ( int32 ) :: nx , ny , n , nbig , dn , m logical :: evenY character ( len = :), allocatable :: errmsg ! Initialization nx = size ( x ) ny = size ( y ) n = nx + ny - 1 ! Memory Allocation allocate ( xmod ( n ), source = zero ) allocate ( ymod ( n ), source = zero ) ! Copy over X & Y if ( nx >= ny ) then xmod ( 1 : nx ) = cmplx ( x , 0.0d0 , real64 ) ymod ( 1 : ny ) = cmplx ( y , 0.0d0 , real64 ) nbig = nx else xmod ( 1 : ny ) = cmplx ( y , 0.0d0 , real64 ) ymod ( 1 : nx ) = cmplx ( x , 0.0d0 , real64 ) nbig = ny end if ! Locate the unspoiled data points dn = n - nbig if ( mod ( dn , 2 ) == 0 ) then n1 = dn / 2 + 1 else n1 = ( dn + 1 ) / 2 + 1 end if n2 = n1 + nbig - 1 end subroutine ! ------------------------------------------------------------------------------ ! Computes the convolution or deconvolution of two signals. ! ! - x: The zero-padded original signal. ! - y: The padded and wrapped response signal. ! - method: +1 for convolution, -1 for deconvolution. ! - rst: The convolved signal. pure subroutine convolve_driver ( x , y , method , rst ) ! Arguments complex ( real64 ), intent ( inout ) :: x (:), y (:) integer ( int32 ), intent ( in ) :: method real ( real64 ), intent ( out ), allocatable :: rst (:) ! Local Variables integer ( int32 ) :: i , n , lwork , nend real ( real64 ) :: fac real ( real64 ), allocatable , dimension (:) :: work complex ( real64 ), allocatable , dimension (:) :: cxy character ( len = :), allocatable :: errmsg ! Generate the workspace array for the transforms & allocate memory n = size ( x ) lwork = 4 * n + 15 allocate ( work ( lwork )) allocate ( rst ( n )) ! Compute the FFT's of both signals call zffti ( n , work ) call zfftf ( n , x , work ) call zfftf ( n , y , work ) ! Compute the scaling factor fac = 1.0d0 / real ( n , real64 ) ! Perform the convolution operation if ( method == 1 ) then ! Multiply the FFT's to convolve cxy = x * y else ! Divide the FFT's to deconvolve cxy = x / y end if ! Compute the inverse transform call zfftb ( n , cxy , work ) if ( method == 1 ) then rst = real ( fac * cxy ) else rst = real ( cxy ) end if end subroutine ! ------------------------------------------------------------------------------ end module","tags":"","loc":"sourcefile\\spectrum_convolve.f90.html"}]}